import React, { useState } from 'react';
import { View, TouchableOpacity, Dimensions } from 'react-native';
import Overlay from 'react-native-modal-overlay';
import { normalize } from '../CommonStyle/componentStyle';
import AntDesign from 'react-native-vector-icons/AntDesign';
import CNotesInstructions from '../CustomComponents/CNotesInstructions';
import InsureLoginLayout from '../Layout/InsureLoginLayout';
import CComments from '../CustomComponents/CComments';
import AddParameter from '../InsureTemplate/AddParameter';
import AddTemplate from '../Templates/AddTemplate';
import DeleteParameter from '../InsureTemplate/DeleteParameter';
import CCalendar from '../CustomComponents/CCalendar';
import CRemarks from '../CustomComponents/CRemarks';
import CDropdownSelect from '../CustomComponents/CDropdownSelect';
import AddScreenOverlay from '../Templates/AddScreenOverlay';
import CAddColumn from '../CustomComponents/CAddColumn';
import FontAwesome5Icon from 'react-native-vector-icons/FontAwesome5';
import CRowAdd from '../CustomComponents/CRowAdd';
import CSummaryDropDown from '../CustomComponents/CSummaryDropDown';
import SwipeLeftView from '../Screens/SwipeLeftView';
import { Global } from '../Common/Global';
import AddDiagnosisTemplate from '../Templates/AddDiagnosisTemplate';
import CIcdView from '../CustomComponents/CIcdView';

function HOverlay(props) {
    const [overlay, setOverlay] = useState(true)
    const components = {
        CNotesOrInstructions: CNotesInstructions,
        InsureLoginLayout: InsureLoginLayout,
        CComments: CComments,
        AddParameterScreen: AddParameter,
        AddTemplate: AddTemplate,
        DeleteParameter: DeleteParameter,
        CCalendar: CCalendar,
        CRemarks: CRemarks,
        CDropdownSelect: CDropdownSelect,
        AddScreenOverlay: AddScreenOverlay,
        CAddColumn: CAddColumn,
        CRowAdd: CRowAdd,
        CSummaryDropDown: CSummaryDropDown,
        AddDiagnosisTemplate: AddDiagnosisTemplate,
        CIcdView: CIcdView
        // SwipeLeftView: SwipeLeftView
    };
    const ViewHOCComponent = components[props.component];
    return (
        <Overlay
            visible={overlay}
            onClose={() => (props.visibility(false))}
            closeOnTouchOutside
            animationType="fadeInUp"
            // easing
            containerStyle={{ backgroundColor: 'rgba(0, 0, 0, 0.20)' }}
            // animationDuration={500}
            childrenWrapperStyle={getPopupContainerStyle()}>
            <View style={{ position: 'absolute', right: 14, top: 10, zIndex: 1 }}>
                <TouchableOpacity
                    onPress={() => setOverlay(false, props.visibility(false))}
                >
                    <FontAwesome5Icon name={"angle-double-down"} size={normalize(20)} color={Global.AppTheme.primary_color} />
                </TouchableOpacity>
            </View>
            <ViewHOCComponent
                {...props}
            />
        </Overlay>
    );

    function getPopupContainerStyle() {
        return {
            position: 'absolute',
            bottom: 0,
            top: Dimensions.get('screen').height * (props.overlayheight ? props.overlayheight : 0.12),
            width: Dimensions.get('window').width,
            borderRadius: 20,
            borderBottomLeftRadius: 0,
            borderBottomRightRadius: 0,
            borderWidth: 2,
            borderColor: '#e0e0e0',
            paddingHorizontal: normalize(5),
            // paddingBottom: 0
        }
    }
}
export default HOverlay;