import React, { useState, useEffect } from 'react';


import {

  TouchableOpacity,
  Text,
  View,
  StyleSheet,
  TextInput,
  Dimensions,
  Keyboard
} from 'react-native';
import { styles } from '../components/styles';
import CustomTextInput from '../CustomComponents/CustomTextInput';
import HOCIcons from '../HOC/HOCIcons';
import Icon from 'react-native-vector-icons/Feather';
import AllergyDropdown from '../components/allergyDropDown';

import { normalize } from '../CommonStyle/componentStyle';

const MedicalInfoSection = ({ formData, setFormData, handleInputChange, getText, fetchedFields = [],
  selectedUserType = 'others', masterAllergyList = [] }) => {

  const [otherAllergyText, setOtherAllergyText] = useState('');


  // Helper Functions


  const getAllergyNamesFromIds = (allergyIds) => {
    if (!allergyIds || !Array.isArray(allergyIds) || !masterAllergyList.length) {
      return [];
    }

    // Look up ID in the passed master list
    return allergyIds.map(id => {
      const match = masterAllergyList.find(item => item.datavalue === id);
      return match ? match.displayvalue : null;
    }).filter(name => name);
  };



  return (
    <View style={minimalStyles.container}>
      {/* Section Header - Minimal */}
      <View style={{
        flexDirection: 'row',
        alignItems: 'center',
        borderBottomWidth: normalize(2),
        borderBottomColor: '#e5e7eb',
        paddingBottom: normalize(8),
        marginBottom: normalize(10),
        marginLeft: normalize(-4),
      }}>

        <Text style={{ fontSize: normalize(14), fontWeight: '600', color: '#094485', }}>{getText('medicalinfo')}</Text>
      </View>

      {/* Two Column Layout */}
      <View style={minimalStyles.twoColumnContainer}>
        {/* Left Column */}
        <View style={minimalStyles.column}>
          {/* ABHA ID */}
          <View style={minimalStyles.inputGroup}>
            <CustomTextInput
              label={getText('abhaid')}
              iconName="shield-alt"
              placeholder=""
              value={formData.abhaId || ''}
              onChangeText={text => handleInputChange('abhaId', text)}
              keyboardType="default"
              style={minimalStyles.compactInput}
              returnKeyType="done"
              onSubmitEditing={() => Keyboard.dismiss()}
              fetchedFields={fetchedFields}
              fieldName="abhaId"
            />
          </View>

          {/* Aadhaar Number */}
          <View style={minimalStyles.inputGroup}>
            <CustomTextInput
              label={getText('adhaarnumber')}
              iconName="credit-card"
              placeholder=""
              keyboardType="number-pad"
              value={formData.aadharId || ''}
              onChangeText={text => {
                const numericText = text.replace(/[^0-9]/g, '');
                handleInputChange('aadharId', numericText);
              }}
              style={minimalStyles.compactInput}
              returnKeyType="done"
              onSubmitEditing={() => Keyboard.dismiss()}
              fetchedFields={fetchedFields}
              fieldName="aadharId"
            />
          </View>


        </View>

        {/* Right Column */}
        <View style={minimalStyles.column}>
          {/* Passport Number */}
          <View style={minimalStyles.inputGroup}>
            <CustomTextInput
              label={getText('passportnumber')}
              iconName="passport"
              placeholder=""
              value={formData.passport || ''}
              onChangeText={text => {
                handleInputChange('passport', text);
              }}
              autoCapitalize="characters"
              keyboardType="default"
              style={minimalStyles.compactInput}
              returnKeyType="done"
              onSubmitEditing={() => Keyboard.dismiss()}
              fetchedFields={fetchedFields}
              fieldName="passport"
            />
          </View>

          {/* Known Allergies - Compact */}
          <View style={minimalStyles.inputGroup}>
            <AllergyDropdown
              selectedAllergies={formData.allergies}
              setSelectedAllergies={allergies =>
                handleInputChange('allergies', allergies)
              }
              otherAllergyText={otherAllergyText}
              setOtherAllergyText={setOtherAllergyText}
              compact={true}
              getText={getText}
              // Dynamically get names using the updated helper
              defaultSelectedNames={getAllergyNamesFromIds(formData.allergies)}
              // Pass the master list to the dropdown
              masterList={masterAllergyList}
            />
          </View>
        </View>
      </View>

      {/* Full Width Medical Remarks */}
      {/* Increased spacing (margin) for better separation */}
      <View style={minimalStyles.fullWidthGroup}>
        <CustomTextInput
          label={getText('medicalremarks')}
          iconName="notes-medical"
          placeholder=""
          value={formData.remarks || ''}
          onChangeText={text => {
            const capitalText = text.toUpperCase();
            handleInputChange('remarks', capitalText);
          }}
          autoCapitalize="characters"
          style={[minimalStyles.remarksInput, { minHeight: normalize(65) }]}
          returnKeyType="done"
          onSubmitEditing={() => Keyboard.dismiss()}
        />
      </View>
    </View>
  );
};

// Updated Minimal Two-Column Styles with Toggle Styles
const minimalStyles = StyleSheet.create({
  container: {
    marginTop: normalize(15),
    paddingHorizontal: normalize(4),
    paddingBottom: normalize(40),
  },
  headerRow: {
    flexDirection: 'row',
    alignItems: 'center',
    marginBottom: normalize(10),
    paddingLeft: normalize(4),
  },
  headerText: {
    fontSize: normalize(16),
    fontWeight: '600',
    color: '#094485',
    marginLeft: 8,
  },
  twoColumnContainer: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    marginHorizontal: normalize(-6),
  },
  column: {
    flex: 1,
    minWidth: '48%',
    paddingHorizontal: normalize(6),
  },
  inputGroup: {
    marginBottom: normalize(15), // Decreased from 12 to pull content tighter
  },
  label: {
    fontSize: normalize(13),
    fontWeight: '600',
    color: '#094485',
    marginBottom: 2, // Adjusted for tighter fit
    marginLeft: 2,
  },
  compactInput: {
    minHeight: normalize(28),
  },

  fullWidthGroup: {
    marginTop: normalize(1),    // Increased from 4 for better visual separation from fields above
    marginBottom: normalize(10), // Increased from 16 to provide more space at the bottom
  },
  remarksInput: {
    // marginTop: -10,
    minHeight: normalize(65),
    alignItems: 'flex-start',
  },
  errorText: {
    color: '#e74c3c',
    fontSize: normalize(11),
    marginTop: normalize(4),
    marginLeft: normalize(4),
    fontWeight: '500',
  },
});
export default MedicalInfoSection;