import React from 'react';
import { View, Text, Keyboard } from 'react-native';
import Icon from 'react-native-vector-icons/Feather';
import FontAwesome5 from 'react-native-vector-icons/FontAwesome5';
import CustomTextInput from '../CustomComponents/CustomTextInput';
import { styles } from '../components/styles';

const AddressSection = ({ formData, handleInputChange, getText, fetchedFields = [],
  selectedUserType = 'others' }) => (
  <View style={{ marginTop: 1 }}>
    {/* Section Header */}
    <View style={[{ flexDirection: 'row', alignItems: 'center', paddingBottom: 8, marginBottom: 10, borderBottomWidth: 1, borderBottomColor: '#e5e7eb' }]}>

      <Text style={{ fontSize: 14, fontWeight: 'bold', color: '#094485' }}>
        {getText('addressinfo')}
      </Text>
    </View>

    {/* House Name */}
    <View
      style={{
        flexDirection: 'row',
        flexWrap: 'wrap',
        justifyContent: 'space-between',
      }}>
      <View style={{ width: '100%', marginBottom: 9 }}>
        <CustomTextInput
          label={getText('housename')}
          isRequired={true}
          iconName="home"
          placeholder=""
          fetchedFields={fetchedFields}
          fieldName='houseName'
          value={formData.houseName || ''}
          onChangeText={text =>
            handleInputChange('houseName', text.toUpperCase())
          }
          autoCapitalize="characters"
          returnKeyType="done"
          onSubmitEditing={() => Keyboard.dismiss()}
        />
      </View>

      {/* PIN Code */}
      <View style={{ width: '48%', marginBottom: 9 }}>
        <CustomTextInput
          label={getText('pincode')}
          iconName="hashtag"
          placeholder=""
          keyboardType="number-pad"
          value={formData.pinCode || ''}
          fetchedFields={fetchedFields}
          fieldName="pinCode"
          onChangeText={text => handleInputChange('pinCode', text)}
          returnKeyType="done"
          onSubmitEditing={() => Keyboard.dismiss()}
        />
      </View>

      {/* Street / Area */}
      <View style={{ width: '48%', marginBottom: 9 }}>
        <CustomTextInput
          label={getText('street')}
          iconName="road"
          placeholder=""
          value={formData.street || ''}
          fetchedFields={fetchedFields}
          fieldName="street"
          onChangeText={text => handleInputChange('street', text.toUpperCase())}
          autoCapitalize="characters"
          returnKeyType="done"
          onSubmitEditing={() => Keyboard.dismiss()}
        />
      </View>

      {/* Post Office */}
      <View style={{ width: '48%', marginBottom: 9 }}>
        <CustomTextInput
          label={getText('postoffice')}
          isRequired={true}
          iconName="mail-bulk"
          placeholder=""
          value={formData.postOffice || ''}
          onChangeText={text =>
            handleInputChange('postOffice', text.toUpperCase())
          }
          fetchedFields={fetchedFields}
          fieldName="postOffice"
          autoCapitalize="characters"
          returnKeyType="done"
          onSubmitEditing={() => Keyboard.dismiss()}
        />
      </View>

      {/* City / District */}
      <View style={{ width: '48%', marginBottom: 9 }}>
        <CustomTextInput
          label={getText('city')}
          iconName="city"
          placeholder=""
          fetchedFields={fetchedFields}
          fieldName="city"
          value={formData.city || ''}
          onChangeText={text => handleInputChange('city', text.toUpperCase())}
          autoCapitalize="characters"
          returnKeyType="done"
          onSubmitEditing={() => Keyboard.dismiss()}
        />
      </View>

      {/* State - now as text input */}
      <View style={{ width: '48%', marginBottom: 9 }}>
        <CustomTextInput
          label={getText('state')}
          iconName="map-marker-alt"
          placeholder=""
          value={formData.state || ''}
          fetchedFields={fetchedFields}
          fieldName="state"
          onChangeText={text => handleInputChange('state', text.toUpperCase())}
          autoCapitalize="characters"
          returnKeyType="done"
          onSubmitEditing={() => Keyboard.dismiss()}
        />
      </View>

      {/* Country */}
      <View style={{ width: '48%', marginBottom: 9 }}>
        <CustomTextInput
          label={getText('country')}
          iconName="globe-asia"
          placeholder=""
          value={formData.country || 'INDIA'}
          fetchedFields={fetchedFields}
          fieldName="country"
          onChangeText={text =>
            handleInputChange('country', text.toUpperCase())
          }
          autoCapitalize="characters"
        />
      </View>

      {/* Landmark */}
      <View style={{ width: '100%', marginBottom: 15 }}>
        <CustomTextInput
          label={getText('landmark')}
          iconName="landmark"
          placeholder=""
          value={formData.landmark || ''}
          fetchedFields={fetchedFields}
          fieldName="landmark"
          onChangeText={text =>
            handleInputChange('landmark', text.toUpperCase())
          }
          autoCapitalize="characters"
          returnKeyType="done"
          onSubmitEditing={() => Keyboard.dismiss()}
        />
      </View>
    </View>
  </View>
);

export default AddressSection;