import React from 'react';
import { APIURLPOR } from '../Common/apiConstants';
import NetworkServiceCall from '../Common/NetworkServiceCall';
import { notifyMessage } from '../CommonStyle/ComponentFunctions';
import { Global } from '../Common/Global';

/**
 * Utility function to send donation certificate via SMS
 * @param {Object} donorData - The donor information
 * @param {string|number} donorData.donorid - The ID of the donor
 * @param {string} donorData.name - The name of the donor
 * @param {string} donorData.mobileno - The mobile number of the donor
 * @param {string} [donorData.organization] - The organization name (default: "AMAG")
 * @returns {Promise<boolean>} - Success status
 */
export const sendCertificateSMS = async (donorData) => {
    const { donorid, name, mobileno, organization = "AMAG" } = donorData;

    if (!donorid) {
        console.warn('sendCertificateSMS: donorid is required');
        return false;
    }
    if (!mobileno) {
        console.warn('sendCertificateSMS: mobileno is required');
        return false;
    }

    try {
        if (Global.betaversion) {
            console.log('🚫 SMS Sending Disabled (Beta Mode active)');
            // notifyMessage('SMS sending is disabled in Beta mode', 3);
            return false;
        }

        console.log(`📤 Sending certificate SMS: DonorID=${donorid}, Name=${name}, Mobile=${mobileno}`);

        const payload = {
            "smstype": "BLDCERTIFICATE",
            "organization": organization,
            "mobileno": mobileno,
            "name": name,
            "donorid": parseInt(donorid),
        };

        // API endpoint: http://122.15.161.229:9393/bldsms/sendsms
        // Construct using APIURLPOR which uses Global.ppPort (9393)
        const apiUrl = `${Global.smsapi}`;
        console.log(`📡 SMS API URL: ${apiUrl}`);
        console.log(`📦 SMS Payload:`, payload);

        const response = await NetworkServiceCall('post', apiUrl, payload);


        if (response?.httpstatus === 200) {
            notifyMessage('✅ Certificate sent via SMS!', 5);
            return true;
        } else {
            console.error('SMS Send Failed:', response);
            notifyMessage('❌ Failed to send certificate SMS', 4);
            return false;
        }
    } catch (error) {
        console.error('Error in sendCertificateSMS:', error);
        notifyMessage('❌ Error sending SMS', 4);
        return false;
    }
};

const CSendSMS = () => {
    return null;
};

export default CSendSMS;

