import React, { useState } from 'react';
import { Text, View, ScrollView, TouchableOpacity, FlatList } from 'react-native';
import { normalize } from '../CommonStyle/componentStyle';
import AntDesign from 'react-native-vector-icons/AntDesign';
import  { isBNUL, isNU, ValueCheck } from '../CommonStyle/ComponentFunctions';
import HOCIcons from '../HOC/HOCIcons';
import CConfirmation from './CConfirmation';
import CBackHandler from './CBackHandler';

function NotesInstructionComments(props) {


    const [data, setData] = useState(props.data);
    const [deleteConfirmation, setDeleteConfirmation] = useState(false);
    const [deleteData, setDeleteData] = useState();


    function moreButton(data) {
        props.buttonFunction(data)
    }

    function renderItem(xxx) {
        return (
            ValueCheck(xxx.item.displayvalue) ?
                <TouchableOpacity
                    disabled={props.disabled}
                    onPress={() => moreButton(xxx.item)}
                    style={{
                        borderWidth: 1,
                        elevation: 2,
                        borderColor: 'lightgrey',
                        padding: normalize(5),
                        marginHorizontal: normalize(3),
                        backgroundColor: 'white',
                        borderRadius: 5,
                        flexDirection: 'row',
                        alignItems: 'center',
                        justifyContent: props.verification ? 'center' : 'flex-start',
                    }}

                >
                    <AntDesign
                        name={props.icon == 'notes' ? 'paperclip' : 'pushpino'}
                        size={props.disabled ? normalize(10) : normalize(10)}
                    />
                    <Text
                        style={{ fontSize: props.disabled ? normalize(12) : normalize(12), paddingLeft: normalize(5) }}>
                        {xxx.item.displayvalue}
                    </Text>
                    {props.deletebutton ?
                        <TouchableOpacity
                            onPress={() => {
                                setDeleteData(xxx.item);
                                setDeleteConfirmation(true);
                            }}
                        >
                            <HOCIcons.Icons
                                name={'trash'}
                                color="#d13737"
                                size={normalize(12)}
                                style={{
                                    textAlign: 'center',
                                    marginHorizontal: normalize(5)
                                }}
                            />
                        </TouchableOpacity>
                        : null}
                </TouchableOpacity> : null
        );
    }

    return (
        <>
            {isBNUL(props.data) ?
                <FlatList
                    data={props.data}
                    horizontal={props.verification}
                    contentContainerStyle={{
                        alignItems: 'center',
                        flexDirection: 'row-reverse',
                        margin: normalize(3)
                    }}
                    renderItem={renderItem}
                    keyExtractor={(item, index) => 'key' + index}
                    showsHorizontalScrollIndicator={false}
                    showsVerticalScrollIndicator={false}
                />
                : null}
            {deleteConfirmation && isNU(deleteData) ? (
                <CBackHandler
                    type={8} // 4 for deletion
                    callBack={(val) => (val == undefined ? null : 
                        setDeleteConfirmation(false),
                        props.deleteCallback(deleteData)
                    )}
                    close={(val) => (val == undefined ? null : setDeleteConfirmation(false))}
                    displaytext={`${'Are you sure you want to delete '}${deleteData.displayvalue}${' ?'}`}
                    displaybuttons={{
                        "iconname": "trash",
                        "button1": "No",
                        "button2": "Yes",
                        "heading": "DELETION"
                    }}

                />
            ) : null}
        </>
    );
}
export default NotesInstructionComments;
