  const {val, blockData, admissiontype, hidefilebutton, hidechartscanbutton} =
    props;
  const navigation = useNavigation();
  const [iconsArr] = useState([
    {
      iconname: 'file-signature',
      stage: 1,
      color: '#F5EEE6',
      selected: true,
      displaytext: 'CREDIT',
      visibility: true,
      iconType: 'FontAwesome5',
      iconColor: '#4A90E2',
      functionid: 'L02',
    },
    {
      iconname: 'vial',
      stage: 5,
      color: '#FFF8E3',
      selected: false,
      displaytext: 'LAB REPORT',
      visibility: true,
      iconType: 'FontAwesome5',
      iconColor: '#50C878',
      functionid: 'L03',
    },
    {
      iconname: 'file-medical',
      stage: 4,
      color: '#F3D7CA',
      selected: false,
      displaytext: 'MEDISEP',
      visibility: true,
      iconType: 'FontAwesome5',
      iconColor: '#FF6B6B',
      functionid: 'L04',
    },
    // {
    //   iconname: 'file-invoice-dollar',
    //   stage: 0,
    //   color: '#E6A4B4',
    //   selected: false,
    //   displaytext: 'Final',
    //   visibility: true,
    //   iconType: 'FontAwesome5',
    //   iconColor: '#9B59B6',
    // },
  ]);
  const [iconsArr1] = useState([
    {
      iconname: 'id-card',
      stage: 1,
      color: '#F5EEE6',
      selected: true,
      displaytext: 'REGISTRATION',
      visibility: true,
      iconType: 'FontAwesome5',
      iconColor: '#4A90E2',
      functionid: 'R01',
    },
    {
      iconname: 'prescription-bottle-alt',
      stage: 5,
      color: '#FFF8E3',
      selected: false,
      displaytext: 'PHARMACY',
      visibility: true,
      iconType: 'FontAwesome5',
      iconColor: '#50C878',
      functionid: 'R02',
    },
    {
      iconname: 'vials',
      stage: 4,
      color: '#F3D7CA',
      selected: false,
      displaytext: 'IP REPORT',
      visibility: true,
      iconType: 'FontAwesome5',
      iconColor: '#FF6B6B',
      functionid: 'R03',
    },
    {
      iconname: 'stethoscope',
      stage: 0,
      color: '#E6A4B4',
      selected: false,
      displaytext: 'OP REPORT',
      visibility: true,
      iconType: 'FontAwesome5',
      iconColor: '#9B59B6',
      functionid: 'R04',
    },
    {
      iconname: 'file-medical',
      stage: 0,
      color: '#E6A4B4',
      selected: false,
      displaytext: 'CONSOLIDATE',
      visibility: true,
      iconType: 'FontAwesome5',
      iconColor: '#9B59B6',
      functionid: 'R05',
    },
  ]);

  const fetchPdfData = async (type, data) => {
    try {
      console.log('Fetching PDF Data:', JSON.stringify(data));
      const {hopapatient, fromdate, todate, hopacredit} = data;
      const buttonapi = `${APIURL}emr/emrcommonget/jrrncommonbillprints ${type},${hopapatient},'${fromdate}','${todate}',${hopacredit},${Global?.userData?.original}`;
      console.log('BUTTONAPI------------------------------------', buttonapi);
      const response = await NetworkServiceCall('get', buttonapi, '');
      console.log(
        'RESPONSEDATA----------------------------------',
        JSON.stringify(response),
      );
      if (response.httpstatus === 200) {
        const billData = response?.data?.bill;
        if (!billData || billData.length === 0) {
          notifyMessage('No Files Found', 4);
          return;
        }
        const transformedData = transformJson(billData)?.data;
        props.navigation.navigate('CPdfGallery', {
          index: 5,
          displayarray: transformedData,
        });
      } else {
        console.log('failed');
        notifyMessage('Fetch error', 4);
      }
    } catch (err) {
      console.error('Fetch error:', err);
      setError?.(err.message); // Safe call if setError is defined
    }
  };
  const onPressSwipe = (val, blockData) => {
    // console.log('kkkkkkkkkk',JSON.stringify(val))
    props.props.closeOverlay();
    switch (val.functionid) {
      case 'L01':
        navigation.navigate('CCreditAllocation', {
          patientData: blockData?.item?.profilecontent?.[0],
        });
        break;
      case 'L02':
        Global.PatientDetails = blockData.item;
        navigation.navigate('PdfPreview', {
          patientData: blockData?.item?.profilecontent?.[0],
          link: blockData?.item?.creditlink,
          name: val.displaytext,
        });
        break;
      case 'L03':
        Global.PatientDetails = blockData.item;
        navigation.navigate('CConsolidationBill', {
          patientData: blockData?.item?.profilecontent?.[0],
          flag: 1,
          name: val.displaytext,
        });
        break;
      case 'L04':
        Global.PatientDetails = blockData.item;
        navigation.navigate('PdfPreview', {
          patientData: blockData?.item?.profilecontent?.[0],
          link: blockData?.item?.mediseplink,
          name: val.displaytext,
        });
        break;
      case 'R01':
        Global.PatientDetails = blockData.item;
        fetchPdfData(1, blockData?.item?.profilecontent?.[0]);
        break;
      case 'R02':
        Global.PatientDetails = blockData.item;
        fetchPdfData(2, blockData?.item?.profilecontent?.[0]);
        break;
      case 'R03':
        Global.PatientDetails = blockData.item;
        fetchPdfData(3, blockData?.item?.profilecontent?.[0]);
        break;
      case 'R04':
        Global.PatientDetails = blockData.item;
        fetchPdfData(4, blockData?.item?.profilecontent?.[0]);
        break;
      case 'R05':
        Global.PatientDetails = blockData.item;
        navigation.navigate('CConsolidationBill', {
          patientData: blockData?.item?.profilecontent[0],
          patientbilltypedisplay: [
            'PHARMACY',
            'REGISTRATION',
            'IP',
            'OP',
            'CANTEEN',
            'ADVANCE',
            'REFUND',
            'PRESCRIPTION',
          ],
          patientbilltypevalue: '1,1,1,1,1,1,1,1',
          flag: 2,
          name: val.displaytext,
        });
        break;
      default:
        break;
    }
  };

  const statusColor =
    admissiontype === 'IP' ? '#FF6B6B' : Global.AppTheme.primary_color;
  const cardBackground = admissiontype === 'IP' ? '#FFF0F0' : '#F0F8FF';

