import React, { memo, useState, useRef } from 'react';
import { View, TextInput, Text, KeyboardAvoidingView, Platform, Animated } from 'react-native';
import FontAwesome5 from 'react-native-vector-icons/FontAwesome5';
import { normalize } from '../CommonStyle/componentStyle';
import HOCIcons from '../HOC/HOCIcons';
import { isNU,isNUQZ } from '../CommonStyle/ComponentFunctions';

const CTextInput = (props) => {

    const [text, setText] = useState(props.data != undefined ? props.data.value : "");
    const [Info, setInfo] = useState(false);
    const [refreshview, setRefreshView] = useState(true);
    const [data, setData] = useState(props.data != undefined ? props.data : {
        itemwidth: "100%",
        displaytext: "Name",
        iconname: 'home',
        value: 45,
        type: 'number-pad',
        editable: true,
        placeholder: "Name",
        decimal: 2,
        icongroup: 5
    });

    const shakeAnimation = useRef(new Animated.Value(0)).current;

    const shake = () => {
        // Reset the animation
        shakeAnimation.setValue(0);
        // Define the shake animation
        Animated.sequence([
            Animated.timing(shakeAnimation, {
                toValue: 0.5,
                duration: 50,
                useNativeDriver: true,
            }),
            Animated.timing(shakeAnimation, {
                toValue: -0.5,
                duration: 50,
                useNativeDriver: true,
            }),
            Animated.timing(shakeAnimation, {
                toValue: 0.5,
                duration: 50,
                useNativeDriver: true,
            }),
            Animated.timing(shakeAnimation, {
                toValue: 0,
                duration: 50,
                useNativeDriver: true,
            }),
        ]).start();
    };

    const shakeInterpolate = shakeAnimation.interpolate({
        inputRange: [-1, 0, 1],
        outputRange: [-10, 0, 10], // Change these values to adjust shake intensity
    });

    const validateEmail = (email) => {
        // Regular expression for basic email validation
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return emailRegex.test(email);
    };

    const validateMobileNumber = (number) => {
        // Regular expression for a 10-digit mobile number
        const mobileRegex = /^\d{10}$/;
        return mobileRegex.test(number);
    };

    function onEndEditingValidation(i) {

        switch (i) {
            case 1: // email validation 
                // console.log('onEndEditingValidation', validateEmail(text));
                if (!validateEmail(text)) {
                    shake();
                    setText("");
                    setRefreshView(false);
                    setTimeout(() => {
                        setRefreshView(true);
                    }, 1000);
                    props.callBack("");
                }
                break;
            case 2: // mobile number validation 
                console.log('validateMobileNumber', text)
                if (!validateMobileNumber(text)) {

                    shake();
                    setText("");
                    setRefreshView(false);
                    setTimeout(() => {
                        setRefreshView(true);
                    }, 1000);
                    props.callBack("");
                }
                else {
                    isNU(props.onEndEditCallback) ? props.onEndEditCallback(text) : null
                }
                break;
            case 3:
                isNU(props.onEndEditCallback) ? props.onEndEditCallback(text) : null
                break;

            default:
                break;
        }

    }

    // const handleChange = (text) => {
    //     // Remove non-numeric characters
    //     const cleaned = text.replace(/\D/g, '');

    //     // Format the number (e.g., (123) 456-7890)
    //     const match = cleaned.match(/(\d{0,3})(\d{0,3})(\d{0,4})/);
    //     const formatted = match[1] ? `(${match[1]}` : '';
    //     if (match[2]) {
    //         formatted += `) ${match[2]}`;
    //     }
    //     if (match[3]) {
    //         formatted += `-${match[3]}`;
    //     }
    //     setText(formatted);
    //     props.callBack != undefined ? props.callBack(formatted) : null;
    // };

    return (
        <Animated.View style={{ transform: [{ translateX: shakeInterpolate }] }}>
            <View style={{
                // padding: 20,
                borderWidth: 0,
                width: data.itemwidth != undefined ? data.itemwidth : '100%'
            }}>


                {/* {data.displaytext != undefined ?
                <Text style={{
                    fontSize: data.dtextsize != undefined ? data.dtextsize : normalize(11),
                    color: 'black',
                    paddingHorizontal: 5,
                    textAlign: data.alignment != undefined ? data.alignment : 'left',
                    fontWeight: data.dfontweight ? data.dfontweight : 'normal'
                }}>
                    {data.displaytext != undefined ? data.displaytext : "Default"}
                </Text>
                : null} */}
                <View style={
                    props.inputstyle ?
                        [props.inputstyle,
                        refreshview ? undefined : { borderColor: 'darkred' }

                        ] :
                        {
                            flexDirection: 'row',
                            borderWidth: isNU(props.CBorderWidth) ? props.CBorderWidth : 1,
                            borderColor: 'lightgrey',
                            borderRadius: 10,
                            alignItems: 'center',
                            height: props.CCommonHeight != undefined ? props.CCommonHeight : normalize(35),
                        }}>

                    <View style={
                        props.custompositiontextviewstyle ?
                            props.custompositiontextviewstyle :
                            {
                                position: 'absolute',
                                top: normalize(-6),
                                left: normalize(10),
                                backgroundColor: 'white',
                                flexDirection: 'row',
                                alignItems: 'center'
                            }}
                    >
                        <Text style={{
                            color: '#164c92',
                            fontSize: normalize(10),
                            textAlign: 'left',
                            fontWeight: 'normal'
                        }}>
                            {" "}{isNU(data.displaytext) ? data.displaytext : null}
                        </Text>
                        {props.required ?
                            <Text style={{
                                color: 'red',
                                fontSize: normalize(10)
                            }}>
                                {" * "}
                            </Text>
                            : null}
                    </View>

                    {props.iconstyle ?
                        <HOCIcons.Icons
                            icongroup={props.iconstyle.icongroup != undefined ? props.iconstyle.icongroup : 5}
                            name={props.iconstyle.iconname != undefined ? props.iconstyle.iconname : "file-alt"}
                            size={props.iconstyle.iconsize != undefined ? props.iconstyle.iconsize : normalize(15)}
                            color={props.iconstyle.iconcolor != undefined ? props.iconstyle.iconcolor : "darkblue"}
                            style={props.iconstyle.style != undefined ? props.iconstyle.style : { paddingHorizontal: 5 }}
                            onPress={() => { props.CIconCallBack != undefined ? props.CIconCallBack(data) : null }}
                        // onPress={() => { shake() }}
                        />
                        : null
                    }
                    {refreshview ?
                        <TextInput
                            style={{
                                borderWidth: 0,
                                flex: 1,
                                // backgroundColor: '#ede7f6',
                                paddingRight: normalize(5),
                                fontSize: data.tfontsize != undefined ? data.tfontsize : normalize(14),
                                height: data.textarea != undefined ? normalize(60) : normalize(35),
                                color: 'black',
                                fontWeight: data.tfontweight != undefined ? data.tfontweight : 'normal'
                            }}
                            onChangeText={val => {
                                if (props.onlyAtoZ) {
                                    // console.log('prevoius val', val);
                                    const filteredInput = val.replace(/[^A-Za-z\s]/g, '').toUpperCase();
                                    // console.log('next val',filteredInput)
                                    setText(filteredInput);
                                    (props.callBack != undefined ? props.callBack(filteredInput) : null);
                                }
                                else {
                                    setText(val);
                                    (props.callBack != undefined ? props.callBack(val) : null);
                                }
                            }}
                            autoCapitalize={data.capitalize != undefined ? data.capitalize : 'none'}
                            textAlign={data.alignment != undefined ? data.alignment : data.type == 'number-pad' ? 'left' : 'left'}
                            keyboardType={data.type != undefined ? data.type : 'default'}
                            // keyboardType={'email-address'}
                            maxLength={data.maxlength != undefined ? data.maxlength : 200}
                            editable={props.disabled ? false : true}
                            multiline={data.textarea != undefined ? data.textarea : false}
                            numberOfLines={data.textarea != undefined ? 8 : 1}
                            placeholder={data.placeholder != undefined ? data.placeholder : null}
                            placeholderTextColor={isNU(data.placeholdercolor) ? data.placeholdercolor : '#e1e1e1'}
                            onBlur={() => setInfo(false)}
                            onFocus={() => setInfo(true)}
                            spellCheck={false}
                            autoCorrect={false}
                            // ref={props.ref ? props.ref : null}
                            onEndEditing={(val) => {
                                isNUQZ(props.validationtype) ? onEndEditingValidation(props.validationtype) : null
                            }}
                            value={text}
                            // value={data.value != undefined ? data.value : ""}
                            {...props}
                        >
                            {/* {data.value != undefined ?
                                data.value : ""} */}
                        </TextInput>
                        :
                        <View style={{
                            borderWidth: 0,
                            flex: 1,
                            // backgroundColor: '#ede7f6',
                            paddingRight: normalize(5),
                            fontSize: data.tfontsize != undefined ? data.tfontsize : normalize(14),
                            height: data.textarea != undefined ? normalize(60) : normalize(35),
                            color: 'black',
                            fontWeight: data.tfontweight != undefined ? data.tfontweight : 'normal'
                        }}>
                        </View>
                    }

                </View>

                {data.positiontext != undefined ?
                    <Text style={{ position: 'absolute', fontSize: normalize(6), color: 'black', paddingHorizontal: 5, textAlign: 'left', fontWeight: 'normal', backgroundColor: 'white' }}>
                        {data.positiontext != undefined ? data.positiontext : " "}
                    </Text>
                    : null}
                {Info && isNU(props.info) || !refreshview ?
                    <View style={{ marginTop: normalize(3), borderRadius: 5, borderWidth: 0, width: '100%', borderColor: 'lightgrey', flexDirection: 'row', alignItems: 'center' }}>
                        <HOCIcons.Entypo
                            icongroup={5}
                            name={"info-with-circle"}
                            size={normalize(10)}
                            color={"grey"}
                            style={{ textAlign: 'center', paddingHorizontal: normalize(3) }}
                        />
                        <Text adjustsFontSizeToFit style={{ width: '90%', color: refreshview ? 'grey' : 'darkred', fontStyle: 'italic', fontSize: normalize(9), textAlign: 'left' }}>
                            {" "}{isNU(props.info) ? props.info : null}
                        </Text>
                    </View>
                    : null}
            </View>
        </Animated.View>
    )
}
export default memo(CTextInput);
