import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { Text, View, ScrollView, Dimensions, FlatList, TouchableOpacity, TextInput, KeyboardAvoidingView, TouchableWithoutFeedback, } from 'react-native';
import { isBNU, isBNUL, isNU, normalize } from '../CommonStyle/ComponentFunctions';
import Overlay from 'react-native-modal-overlay';
import HOCIcons from '../HOC/HOCIcons';
import CDetailView from './CDetailView';
import themes from '../Common/CommonTheme';
import CAwesomeButton from './CAwesomeButtonLab';
import { Global } from '../Common/Global';

export default function CEditorOverlay(props) {

  const [refresh, setRefresh] = useState(0);
  const [overlay, setOverlay] = useState(true);
  const [autofocus, setAutoFocus] = useState(false);
  const [Comments, setComments] = useState(isNU(props.data) ? props.data : null);

  function getOverlayChildrenWrapperStyle() {

    return isNU(props.overlaystyle) ?
      props.overlaystyle
      :
      {
        borderRadius: 10,
        height: Dimensions.get('window').height * 0.3,
        borderWidth: 3,
        borderColor: 'darkblue',
        alignSelf: 'center',
        width: Dimensions.get('screen').width * 0.9,
        alignItems: 'center',
        justifyContent: 'flex-start',
        padding: 0,
        backgroundColor: 'transparent'
      };
  }

  function FnOnchangeText(text) {
    setAutoFocus((prevAutoFocus) => false);
    setComments((prevComments) => text);
    props.data = text;
    props.callback(text);
    // memoizedCallback(text);
  }

  const FnEditSomeContent = useMemo(() => { // to edit only the added text , first text cannot be edited because it is restricted by its length 
    return (text) => {
      const newTextAfterHello = text.substring(props.editcontent.length);
      const newNewText = `${props.editcontent}${newTextAfterHello}`;
      setComments(newNewText);
      props.callback(newNewText);
    };
  }, []);

  const handleChangeText = useMemo(() => {
    return props.editcontentstatus ? FnEditSomeContent : FnOnchangeText;
  }, [props.editcontentstatus]);

  return (

    // overlay ? (
    <Overlay
      visible={overlay}
      onClose={() => {
        setAutoFocus(false),
          setOverlay(false),
          setRefresh(refresh + 1),
          (isBNU(props.OverlayClose) ? props.OverlayClose(true) : null)
      }}
      closeOnTouchOutside
      animationType="zoomIn"
      containerStyle={{ backgroundColor: 'transparent' }}
      childrenWrapperStyle={getOverlayChildrenWrapperStyle()}
      animationDuration={500}>
      <CDetailView
        overlay={true}
      >
        <View style={{ borderRadius: 10, flex: 1, justifyContent: 'center', alignItems: 'center', backgroundColor: 'white' }}>
          <View
            style={{
              flexDirection: 'row',
              justifyContent: 'space-between',
              alignItems: 'center',
              width: '100%',
              marginTop: normalize(5)
            }}>
            <Text
              style={{
                color: Global.AppTheme.primary_color,
                fontSize: normalize(11),
                fontWeight: 'bold',
              }}>
              {' '}
            </Text>
            <Text
              style={{
                color: Global.AppTheme.primary_color,
                fontSize: normalize(12),
                fontWeight: 'bold',
              }}>
              {isBNU(props.heading) ? props.heading : 'COMMENTS'}
            </Text>
            <TouchableOpacity
              onPress={() => {
                setAutoFocus(false),
                  setOverlay(false),
                  setRefresh(refresh + 1),
                  (isBNU(props.OverlayClose) ? props.OverlayClose(true) : null)
              }}>
              <HOCIcons.FontAwesome5 name={'angle-double-down'} size={normalize(25)} style={{ marginHorizontal: normalize(5) }} color={Global.AppTheme.primary_color} />
            </TouchableOpacity>
          </View>
          <View style={{ flex: 1, width: '100%', alignSelf: 'center', justifyContent: 'flex-start', alignItems: 'center' }}>


            <TextInput
              style={{
                // flex: 1,
                minHeight: normalize(100),
                fontWeight: 'bold',
                borderWidth: 1,
                borderColor: '#bdbdbdc4',
                borderRadius: 6,
                width: '95%',
                textAlignVertical: 'top',
                paddingVertical: normalize(10),
                paddingHorizontal: normalize(10),
                backgroundColor: '#ebebebc4',
                marginVertical: normalize(5),
                color: 'black',
                fontSize: normalize(15)
              }}
              // autoFocus={autofocus ? true : false}
              value={Comments}
              underlineColorAndroid="transparent"
              placeholder="Type Here"
              placeholderTextColor="lightgrey"
              onChangeText={handleChangeText}
              numberOfLines={5}
              multiline={props.disablemultiline ? false : true}
            >
              {/* {props.data ? props.data : null} */}
            </TextInput>
          </View>


          <View style={{ paddingHorizontal: normalize(10), flexDirection: 'row', alignItems: 'flex-start', justifyContent: 'flex-start', borderWidth: 0, width: '100%' }}>
            <CAwesomeButton
              callback={(k) => {
                setAutoFocus(false),
                  setOverlay(false),
                  setRefresh(refresh + 1),
                  (isBNU(props.onsavecallback) ? props.onsavecallback(Comments) : null)
              }}
              buttonstyle={{
                'borderRadius': 10,
                'borderWidth': 0.5,
                'height': Dimensions.get('screen').height * 0.07,
                'width': Dimensions.get('screen').height * 0.07,
                'backgroundColor': '#f2f3ff',
                'paddingHorizontal': 0,
                'raiseLevel': 4,
                'paddingBottom': 0,
                'borderColor': 'lightblue',
                'paddingTop': 0,
                'style': {
                  padding: 0,
                  marginHorizontal: normalize(2),
                  marginVertical: normalize(2)
                }
              }}
              viewstyle={{
                borderWidth: 0,
                borderRadius: 0,
                justifyContent: 'center',
                alignItems: 'center'
              }}
              icon={
                props.footericon ?
                  props.footericon :
                  {
                    'icongroup': 1,
                    'name': 'select1',
                    'color': 'darkblue',
                    'size': normalize(20),
                    'style': {
                      textAlign: 'center'
                    }
                  }}
              text={{
                fontSize: normalize(7),
                fontWeight: 'bold',
                color: 'darkblue',
                textAlign: 'center'
              }}
              displaytext={props.footerbuttontext ? props.footerbuttontext : 'Select'}
            />
          </View>
        </View>
      </CDetailView>
    </Overlay>
    // ) : null
  );
}
