import React, { useEffect, useRef } from 'react';
import moment from 'moment';
import axios from 'axios';
import RNFetchBlob from 'react-native-blob-util';
import { notifyMessage, isPermitted } from '../CommonStyle/ComponentFunctions';
import { APIURL, EMRAPI } from '../Common/apiConstants';
import NetworkServiceCall from '../Common/NetworkServiceCall';
import { Global } from '../Common/Global';

const RegistrationLabelPrinter = ({ donationId, onComplete }) => {
    const hasStartedPrint = useRef(false);

    useEffect(() => {
        console.log('🟡 useEffect triggered | donationId:', donationId);

        // 🔥 RESET when donationId changes
        hasStartedPrint.current = false;
        console.log('🔄 Reset hasStartedPrint to false');

        if (donationId) {
            console.log('✅ Calling handleRegistrationLabelPrint()');
            handleRegistrationLabelPrint();
        }
    }, [donationId]);



    const handleRegistrationLabelPrint = async () => {
        if (hasStartedPrint.current) {
            console.log('⛔ Print already started, skipping duplicate call');
            return;
        }

        hasStartedPrint.current = true;
        console.log('🚀 Starting Registration Label Print Flow');
        console.log('🧾 Donation ID:', donationId);

        try {
            /* ===============================
               PERMISSION CHECK
            =============================== */
            console.log('🔐 Checking permissions...');
            const permitted = await isPermitted();
            console.log('🔐 Permission result:', permitted);

            if (!permitted) {
                console.log('⛔ Permission denied');
                return;
            }

            /* ===============================
               1️⃣ FETCH LABEL PDF
            =============================== */
            const fetchUrl =
                `${APIURL}bldjr/jrcommonreport/` +
                `rnbbdonationidcardlabelprinter(${donationId})/0/RegistrationLabel`;

            console.log('📡 [FETCH PDF] URL:', fetchUrl);

            const pdfResponse = await RNFetchBlob.config({
                fileCache: true,
                appendExt: 'pdf',
            }).fetch('GET', fetchUrl);

            console.log('📡 [FETCH PDF] Status:', pdfResponse.info().status);
            console.log('📡 [FETCH PDF] Headers:', pdfResponse.info().headers);

            if (pdfResponse.info().status !== 200) {
                console.log('❌ PDF fetch failed');
                notifyMessage('Failed to fetch label', 2);
                return;
            }

            const localFilePath = pdfResponse.path();
            console.log('📄 PDF saved at path:', localFilePath);

            /* ===============================
               2️⃣ UPLOAD FILE
            =============================== */
            const fileName =
                `RegistrationLabel_${donationId}_${moment().format('DDMMYYYY_HHmmss')}.pdf`;

            const uploadUrl = `${APIURL}bldfile/fileupload/emr/printdocument`;

            console.log('📤 Upload URL:', uploadUrl);
            console.log('📤 Uploading file:', fileName);

            const formData = new FormData();
            formData.append('file', {
                uri: `file://${localFilePath}`,
                type: 'application/pdf',
                name: fileName,
            });

            // OPTIONAL: if backend expects filename separately
            formData.append('filename', fileName);

            const uploadResponse = await axios.post(
                uploadUrl,
                formData,
                {
                    headers: {
                        'Content-Type': 'multipart/form-data',
                        Authorization: `Bearer ${Global.jwtToken}`,
                    },
                    timeout: 30000, // avoid false network error
                }
            );

            console.log('📬 Upload status:', uploadResponse.status);
            console.log('📬 Upload response:', uploadResponse.data);

            const uploadedFileName =
                uploadResponse.data?.fileuri || fileName;



            if (!uploadedFileName) {
                console.log('❌ Invalid upload response: fileuri missing');
                notifyMessage('Invalid upload response', 2);
                return;
            }

            /* ===============================bldfile/fileupload/emr/signature
               3️⃣ PRINT FILE
            =============================== */

            const printerPath = String.raw`\\10.199.202.32\BLOODBANK_LABEL_PRINTER`;

            const printPayload = {
                heading1: uploadedFileName,
                heading2: printerPath,
            };

            console.log('🖨️ [PRINT] API URL:', `${Global.getBaseUrl()}/bldpdf/orders/printfile/`);
            console.log('🖨️ [PRINT] Payload:', JSON.stringify(printPayload));

            const printResponse = await axios.post(
                `${Global.getBaseUrl()}/bldpdf/orders/printfile/`,
                printPayload
            );

            console.log('🎯 [PRINT] Axios Status:', printResponse.status);
            console.log('🎯 [PRINT] Axios Headers:', printResponse.headers);
            console.log('🎯 [PRINT] Response Data:', printResponse.data);

            if (printResponse?.data?.httpstatus === 200) {
                console.log('✅ Print success');
                notifyMessage('Printed Successfully', 1);
            } else {
                console.log('❌ Print failed response:', printResponse?.data);
                notifyMessage('Print Failed', 2);
            }

            /* ===============================
               4️⃣ CLEANUP
            =============================== */
            console.log('🧹 Deleting local file:', localFilePath);
            await RNFetchBlob.fs.unlink(localFilePath);
            console.log('🧹 Local file deleted successfully');

        } catch (error) {
            console.error('🔥 PRINT FLOW ERROR 🔥');
            console.error('Error message:', error?.message);
            console.error('Error object:', error);

            if (error?.response) {
                console.error('❗ Axios error status:', error.response.status);
                console.error('❗ Axios error data:', error.response.data);
            }

            notifyMessage('Print error occurred', 2);
        } finally {
            console.log('🔚 Print flow completed');
            if (onComplete) onComplete();
        }
    };

    return null;
};

export default RegistrationLabelPrinter;
