import React from 'react';
import { Dimensions } from 'react-native';
import { View } from 'react-native';
import { CFooterShadow } from '../CommonStyle/ComponentFunctions';
import { Global } from '../Common/Global';

/**
 * CFooterView Component
 * 
 * A customizable footer component with consistent styling
 * 
 * @param {Object} props - Component props
 * @param {Object} props.style - Additional styles to apply to the footer
 * @param {React.ReactNode} props.children - Content to render inside the footer
 * @returns {React.ReactElement} Rendered footer component
 */
const CFooterView = ({ style, children }) => {
  const screenHeight = Dimensions.get('screen').height;
  
  return (
    <View
      style={[
        {
          // Shadow can be enabled by uncommenting:
          // ...CFooterShadow(),
          minHeight: screenHeight * 0.06,
          paddingVertical: 5,
          justifyContent: 'center',
          backgroundColor: 'white',
          borderTopWidth: 1,
          borderTopColor: 'lightgrey',
        },
        style,
      ]}
    >
      {children}
    </View>
  );
};

export default CFooterView;