import React, { useState, useEffect, useRef } from 'react';
import { Text, View, FlatList, TouchableOpacity, Dimensions, ActivityIndicator } from 'react-native';
import FontAwesome5 from 'react-native-vector-icons/FontAwesome5';
import { normalize } from '../CommonStyle/componentStyle';
import { APIURL } from '../Common/apiConstants';
import { notifyMessage } from '../CommonStyle/ComponentFunctions';
import { Global } from '../Common/Global';
import NetworkServiceCall from '../Common/NetworkServiceCall';
import Icons from '../Common/Icons';

const CCalendar = () => {

    const { width, height } = Dimensions.get('screen')
    const flatlistRef = useRef();
    const dividedWidth = width / 7;
    const [data, setData] = useState()
    const [refresh, setRefresh] = useState(0)
    const [isLoading, setIsLoading] = useState(false);
    const [footerData, setFooterData] = useState()
    const months = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
    const d = new Date();
    const [monthinno, setMonthInNo] = useState(d.getMonth())
    let monthName = months[monthinno];
    const [year, setYear] = useState(d.getFullYear())

    useEffect(() => {
        // getConsultation(Global.userData.hosuconsultant, year, monthinno)
        getConsultation(Global.userData.hosuconsultant, year, monthinno)
    }, [])

    function getConsultation(consultant, year, month) {
        var monthReal = month + 1
        let buttonapi = APIURL + 'emr/emrcommonget/rnhococonsultationhistoryemr ' + consultant + ',' + year + ',' + monthReal;
        console.log('CCalendar........',buttonapi);
       
        setIsLoading(true)
        NetworkServiceCall("get", buttonapi, "")
            .then(function (response) {
                if (response.httpstatus == 200 && response.data != null && response.data != undefined) {
                    setIsLoading(false)
                    setData(response.data.bookingdata)
                }
                else {
                    setIsLoading(false)
                    notifyMessage("Consultation not available,Please try again later",4)
                }
            })
    }

    function IncrementMonth() {
        setFooterData(null)
        if (monthinno != 11) {
            if (monthinno != d.getMonth()) {
                if (monthinno < 11) {
                    setMonthInNo(monthinno + 1)
                } else {
                    setYear(year + 1)
                    setMonthInNo(0)
                }
                getConsultation(Global.userData.hosuconsultant, year, monthinno + 1)
            }
        } else {
            setMonthInNo(0)
            setYear(year + 1)
            getConsultation(Global.userData.hosuconsultant, year + 1, 0)
        }
    }

    function DecrementMonth() {
        if (monthinno != 0) {
            setFooterData(null)
            if (monthinno > 0) {
                setMonthInNo(monthinno - 1)
            } else {
                setYear(year - 1)
                setMonthInNo(11)
            }
            getConsultation(Global.userData.hosuconsultant, year, monthinno - 1)
        } else {
            setYear(year - 1)
            setMonthInNo(11)
            getConsultation(Global.userData.hosuconsultant, year - 1, 11)
        }
    }

    function footerComponent() {
        return (
            <View style={{ marginBottom: 10 }}>
                {footerData != undefined && footerData.data != undefined ?
                    <View
                        style={{ backgroundColor: '#fff', height: normalize(35), alignItems: 'center', justifyContent: 'space-evenly', flexDirection: 'row' }}>
                        <View style={{ flexDirection: 'row', alignItems: 'center', width: '50%', justifyContent: 'center' }}>
                            <Icons.FontAwesome5 name={"calendar-day"} color={"black"} size={normalize(20)} />
                            <Text style={{ fontWeight: 'bold', fontSize: normalize(15), color: 'black', paddingLeft: normalize(10) }}>
                                {footerData.displaytext + "/" + monthName + "/" + year}
                            </Text>
                        </View>
                    </View> : null}

                {footerData != undefined && footerData.data != undefined ?
                    <FlatList
                        nestedScrollEnabled={true}
                        data={footerData.data}
                        style={{ width: width, }}
                        renderItem={renderFooterView}
                        keyExtractor={(item, index) => 'key' + index}
                        listKey={(item, index) => 'key' + index} /> : null}
            </View>
        )
    }

    function renderFooterView({ item }) {
        return (
            <View style={{}}>
                <TouchableOpacity onPress={() => { item.expand = !item.expand, setRefresh(refresh + 1) }}
                    style={{ flexDirection: 'row', backgroundColor: '#fff', alignItems: 'center', justifyContent: 'space-between', marginTop: 2, paddingHorizontal: 10 }}>
                    <View style={{ flexDirection: 'row', alignItems: 'center', }}>
                        <Icons.FontAwesome5 name={item.iconname != undefined ? item.iconname : "file-alt"} color={"#164d8e"} size={normalize(13)} style={{ paddingRight: 10 }} />
                        <Text style={{ fontSize: normalize(14), fontWeight: 'bold', color: '#164d8e', paddingVertical: normalize(3) }}>{item.bookingname}</Text>
                    </View>
                    <View style={{ flexDirection: 'row', alignItems: 'center', }}>
                        <Icons.FontAwesome5 name={"rupee-sign"} color={"#164d8e"} size={normalize(15)} />
                        <Text style={{ color: '#164d8e', fontWeight: 'bold', fontSize: normalize(18), paddingLeft: 10 }}>{item.amount != undefined ? item.amount : item.tokenarray != undefined && item.tokenarray.length > 0 ? item.tokenarray[0].amount : ""}</Text>
                    </View>
                </TouchableOpacity>
                <View>
                    <FlatList
                        data={item.tokenarray}
                        renderItem={(data) => renderTokens(data, footerData)}
                        numColumns={4}
                        style={{ width: '100%', paddingHorizontal: 20 }}
                        contentContainerStyle={{ alignSelf: 'center' }}
                        listKey={(item, index) => 'key' + index}
                        keyExtractor={(item, index) => 'key' + index}
                        initialNumToRender={10}
                    />
                </View>
            </View>
        )
    }

    function renderItem({ item }) {
        return (
            <TouchableOpacity style={{
                width: dividedWidth, alignItems: 'center', paddingTop: 5,
                borderWidth: 0.5, backgroundColor: item.data != undefined && item.data.length > 0 ? "#f4fcf7" : "#fff",
            }}
            disabled={true}    
            onPress={() => item.data != undefined && item.data.length > 0 ? getDateTokens(item) : (getDateTokens(item), notifyMessage("Sorry , No Tokens Found"))}
            >
                <View style={{
                    alignItems: 'center', justifyContent: 'center',
                }}>
                    <Text style={{
                        color: item.data != undefined && item.data.length > 0 ? "green" : "#b6b5b7", fontSize: normalize(20), fontWeight: 'bold', textShadowColor: '#b6b5b7',
                        textShadowOffset: { width: -1, height: 1 },
                        textShadowRadius: 3
                    }}>{item.displaytext == 0 ? "" : item.displaytext}</Text>
                </View>
                <View style={{
                    flexDirection: 'row', width: '100%', flex: 1, alignItems: 'center',
                    justifyContent: 'space-between', flexWrap: 'wrap', paddingHorizontal: 0,
                    paddingTop: normalize(5), paddingBottom: normalize(5)
                }}>
                </View>
            </TouchableOpacity>
        )
    }

    return (
        <View style={{}}>
            {isLoading ?
                <ActivityIndicator size={normalize(30)} style={{ marginTop: normalize(10) }} color="#d808c3" /> : null}
            <View style={{ backgroundColor: 'transparent' }}>
                <View style={{ flexDirection: 'row', alignSelf: 'center', alignItems: 'center', justifyContent: 'space-between', width: '50%' }}>
                    <FontAwesome5 name="arrow-left" color="black" size={normalize(20)} onPress={() => DecrementMonth()} />
                    <Text style={{ fontSize: normalize(16), color: 'black', paddingHorizontal: 10, }}>{monthName} {year}</Text>
                    <FontAwesome5 name="arrow-right" color="black" size={normalize(20)} onPress={() => IncrementMonth()} />
                </View>
            </View>
            <View style={{ flexDirection: 'row', height: normalize(20), alignItems: 'center', justifyContent: 'center' }}>
                {["Sun", "Mon", "Tue", "Wed", "Thr", "Fri", "Sat"].map((week, i) => {
                    return (
                        <View key={i} style={{ width: dividedWidth, alignItems: 'center', borderWidth: 0.5, }}>
                            <Text style={{ fontSize: normalize(12), fontWeight: 'bold', color: i == 0 ? "red" : "black" }}>{week}</Text>
                        </View>)
                })}
            </View >
            <FlatList
                ref={flatlistRef}
                data={data}
                style={{ width: '100%', marginBottom: normalize(85) }}
                renderItem={renderItem}
                keyExtractor={(item) => item.displaytext}
                numColumns={7}
                ListFooterComponent={footerComponent}
                ListFooterComponentStyle={{ width: width }}
            />
        </View>
    )
}
export default CCalendar;