import React, { useRef, useState, useEffect } from 'react';
import { View, Text, TouchableOpacity, SafeAreaView, StyleSheet, StatusBar, Alert, Platform, ActivityIndicator } from 'react-native';
import { useNavigation } from '../Navigation/PageNavigation';
import ImagePicker from 'react-native-image-crop-picker';

const CameraScreen = ({ route }) => {
  const navigation = useNavigation();
  // On web, params might need to be accessed differently depending on navigation setup, 
  // but let's assume route prop is passed correctly by PageNavigation.js
  const onPhotoCapture = route?.params?.onPhotoCapture;
  const [loading, setLoading] = useState(true);

  // Ref for file input element on web
  const fileInputRef = useRef(null);

  useEffect(() => {
    if (Platform.OS === 'web') {
      setLoading(false);
      // Trigger file input click immediately on mount
      if (fileInputRef.current) {
        fileInputRef.current.click();
      }
    } else {
      openNativeCamera();
    }
  }, []);

  const openNativeCamera = async () => {
    try {
      const image = await ImagePicker.openCamera({
        width: 800,
        height: 600,
        compressImageQuality: 0.5,
        cropping: false,
        includeExif: false,
        mediaType: 'photo',
      });

      const capturedPhoto = {
        uri: image.path,
        type: 'image/jpeg',
        fileName: `photo_${Date.now()}.jpg`,
        fileSize: image.size,
        width: image.width,
        height: image.height,
      };

      if (onPhotoCapture) {
        onPhotoCapture(capturedPhoto);
      }
      navigation.goBack();
    } catch (error) {
      if (error.code === 'E_USER_CANCELLED') {
        navigation.goBack();
      } else {
        Alert.alert('Error', 'Failed to capture photo', [
          { text: 'OK', onPress: () => navigation.goBack() }
        ]);
      }
    }
  };

  const handleWebFileChange = (event) => {
    const file = event.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        const capturedPhoto = {
          uri: e.target.result, // Data URL
          type: file.type,
          fileName: file.name,
          fileSize: file.size,
          // width/height not easily available without loading image, but maybe not critical for now
        };

        if (onPhotoCapture) {
          onPhotoCapture(capturedPhoto);
        }
        navigation.goBack();
      };
      reader.readAsDataURL(file);
    } else {
      // User cancelled or no file selected
      navigation.goBack();
    }
  };

  if (Platform.OS === 'web') {
    return (
      <View style={styles.container}>
        <View style={styles.webContainer}>
          <Text style={styles.messageText}>Select an image or take a photo</Text>

          <input
            type="file"
            accept="image/*"
            capture="camera"
            ref={fileInputRef}
            onChange={handleWebFileChange}
            style={{ display: 'none' }}
          // In some browsers 'display: none' prevents triggering via ref, 
          // but usually works. If not, use opacity: 0 and absolute position.
          />

          <TouchableOpacity
            style={styles.button}
            onPress={() => fileInputRef.current && fileInputRef.current.click()}
          >
            <Text style={styles.buttonText}>Open Camera / Gallery</Text>
          </TouchableOpacity>

          <TouchableOpacity
            style={[styles.button, styles.cancelButton]}
            onPress={() => navigation.goBack()}
          >
            <Text style={styles.buttonText}>Cancel</Text>
          </TouchableOpacity>
        </View>
      </View>
    );
  }

  return (
    <SafeAreaView style={styles.container}>
      <StatusBar barStyle="light-content" backgroundColor="black" />
      <View style={styles.messageContainer}>
        <ActivityIndicator size="large" color="#ffffff" />
        <Text style={styles.messageText}>Opening Camera...</Text>
      </View>
    </SafeAreaView>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: 'black'
  },
  messageContainer: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    padding: 20
  },
  messageText: {
    color: 'white',
    fontSize: 18,
    textAlign: 'center',
    marginBottom: 20
  },
  webContainer: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    backgroundColor: '#000',
  },
  button: {
    backgroundColor: '#094485',
    paddingHorizontal: 20,
    paddingVertical: 12,
    borderRadius: 8,
    marginTop: 10,
    minWidth: 200,
    alignItems: 'center',
  },
  cancelButton: {
    backgroundColor: '#dc3545',
  },
  buttonText: {
    color: 'white',
    fontSize: 16,
    fontWeight: '600',
  }
});

export default CameraScreen;
