import React, { useState } from 'react';
import {
  View,
  Text,
  ScrollView,
  TouchableOpacity,
  StyleSheet,
  Dimensions
} from 'react-native';
import { t } from '../components/Transalation'; // Import your translation function

const { width } = Dimensions.get('window');

const BloodDonationConsent = ({
  onAccept,
  showCheckbox = true,
  compact = false,
  language = 'en' // Add language prop
}) => {
  const [isAccepted, setIsAccepted] = useState(false);

  const handleAccept = () => {
    setIsAccepted(!isAccepted);
    if (onAccept) {
      onAccept(!isAccepted);
    }
  };

  return (
    <View style={[styles.container, compact && styles.containerCompact]}>
      <ScrollView
        style={styles.scrollView}
        contentContainerStyle={styles.contentContainer}
        showsVerticalScrollIndicator={false}
      >
        <View style={styles.consentBox}>
          <Text style={styles.consentTitle}>
            {t('consentTitle', language)}
          </Text>

          <View style={styles.divider} />

          <Text style={styles.consentText}>
            {t('consentText1', language)}
          </Text>

          <Text style={styles.consentText}>
            {t('consentText2', language)}
          </Text>

          <Text style={styles.consentText}>
            {t('consentText3', language)}
          </Text>

          <Text style={styles.consentText}>
            {t('consentText4', language)}
          </Text>

          <Text style={styles.consentText}>
            {t('consentText5', language)}
          </Text>

          <Text style={styles.consentText}>
            {t('consentText6', language)}
          </Text>

          <View style={styles.testList}>
            <Text style={styles.testItem}>• {t('testHepatitis', language)}</Text>
            <Text style={styles.testItem}>• {t('testHIV', language)}</Text>
            <Text style={styles.testItem}>• {t('testSyphilis', language)}</Text>
            <Text style={styles.testItem}>• {t('testMalaria', language)}</Text>
          </View>

          <Text style={styles.consentText}>
            {t('consentText7', language)}
          </Text>

          <Text style={styles.consentText}>
            {t('consentText8', language)}
          </Text>

          {/* <View style={styles.acknowledgment}>
            <Text style={styles.acknowledgmentTitle}>
              {t('acknowledgmentTitle', language)}
            </Text>
            <Text style={styles.acknowledgmentText}>
              {t('acknowledgmentText', language)}
            </Text>
          </View> */}
        </View>
      </ScrollView>

      {showCheckbox && (
        <TouchableOpacity
          style={styles.checkboxContainer}
          onPress={handleAccept}
          activeOpacity={0.7}
        >
          <View style={[styles.checkbox, isAccepted && styles.checkboxChecked]}>
            {isAccepted && <Text style={styles.checkmark}>✓</Text>}
          </View>
          <Text style={styles.checkboxLabel}>
            {t('consentCheckbox', language)}
          </Text>
        </TouchableOpacity>
      )}
    </View>
  );
};
const styles = StyleSheet.create({
  container: {
    backgroundColor: '#ffffff',
    borderRadius: 12,
    padding: 3,
    marginBottom: 0,
    borderWidth: 1,
    borderColor: '#e0e0e0',
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.1,
    shadowRadius: 4,
    // elevation: 3,
  },
  containerCompact: {
    padding: 12,
    marginBottom: 1,
  },
  header: {
    alignItems: 'center',
    marginBottom: 1,
    paddingBottom: 1,
    borderBottomWidth: 2,
    borderBottomColor: '#094485',
  },
  hospitalBadge: {
    width: 50,
    height: 50,
    borderRadius: 25,
    backgroundColor: '#f0f8ff',
    justifyContent: 'center',
    alignItems: 'center',
    marginBottom: 8,
  },
  badgeText: {
    fontSize: 24,
  },
  title: {
    fontSize: 18,
    fontWeight: '700',
    color: '#094485',
    textAlign: 'center',
    marginBottom: 2,
  },
  subtitle: {
    fontSize: 13,
    color: '#666',
    fontStyle: 'italic',
  },
  scrollView: {
    maxHeight: "100%", // Reduced from 350
  },
  contentContainer: {
    paddingBottom: 1, // Reduced padding
  },
  consentBox: {
    backgroundColor: '#fafafa',
    padding: 1, // Reduced from 14
    borderRadius: 8,
    // borderLeftWidth: 4,
    // borderLeftColor: '#094485',
  },
  consentTitle: {
    fontSize: 14, // Slightly smaller
    fontWeight: '700',
    color: '#094485',
    textAlign: 'center',
    marginBottom: 1, // Reduced from 12
    letterSpacing: 0.5,
  },
  divider: {
    height: 1,
    backgroundColor: '#d0d0d0',
    marginVertical: 4, // Reduced from 12
  },
  consentText: {
    fontSize: 13, // Reduced from 13
    lineHeight: 18, // Reduced from 20
    color: '#333',
    marginBottom: 4, // Reduced from 10
    textAlign: 'justify',
  },
  bold: {
    fontWeight: '700',
    color: '#094485',
  },
  testList: {
    backgroundColor: '#fff',
    padding: 1,
    borderRadius: 6,
    marginVertical: 1,
    borderWidth: 1,
    borderColor: '#e0e0e0',
  },
  testItem: {
    fontSize: 13,
    color: '#444',
    marginVertical: 1,
    paddingLeft: 8,
  },
  acknowledgment: {
    backgroundColor: '#e8f4f8',
    padding: 1,
    borderRadius: 0,
    marginTop: 0,
  },
  acknowledgmentTitle: {
    fontSize: 14,
    fontWeight: '700',
    color: '#094485',
    marginBottom: 3,
  },
  acknowledgmentText: {
    fontSize: 12,
    color: '#555',
    fontStyle: 'italic',
    lineHeight: 18,
  },
  checkboxContainer: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingVertical: 12,
    paddingHorizontal: 8,
    marginTop: 12,
    backgroundColor: '#f8f8f8',
    borderRadius: 8,
    borderWidth: 1,
    borderColor: '#ddd',
  },
  checkbox: {
    width: 24,
    height: 24,
    borderRadius: 4,
    borderWidth: 2,
    borderColor: '#094485',
    marginRight: 10,
    justifyContent: 'center',
    alignItems: 'center',
    backgroundColor: '#fff',
  },
  checkboxChecked: {
    backgroundColor: '#094485',
  },
  checkmark: {
    color: '#fff',
    fontSize: 16,
    fontWeight: 'bold',
  },
  checkboxLabel: {
    fontSize: 13,
    color: '#333',
    flex: 1,
    fontWeight: '500',
  },
  signatureInstruction: {
    backgroundColor: '#fff8e1',
    padding: 10,
    borderRadius: 6,
    marginTop: 8,
    borderLeftWidth: 3,
    borderLeftColor: '#ffc107',
  },
  instructionText: {
    fontSize: 12,
    color: '#856404',
    textAlign: 'center',
    fontStyle: 'italic',
  },
});

export default BloodDonationConsent;