import React, { useState, useContext } from 'react'
import { View, Text, TouchableOpacity, FlatList, Dimensions, Image } from 'react-native'
import { Global } from '../../Common/Global'
import Icons from '../../Common/Icons'
import { isBNUL, isNU, isNUQ, ValueCheck } from '../../CommonStyle/ComponentFunctions'
import { normalize } from '../../CommonStyle/componentStyle'
import EmrResponseComponentContext from '../../Handlers/emrResponseComponentContext'
import STextInput from '../../StaticComponents/STextInput'
import { manageContext } from '../../Handlers/manageContext'

export default function CBSA(props) {
    const { responseJSON, setResponseJSON } = useContext(EmrResponseComponentContext);
    const stemplate = props.stemplate ?? false;
    const { contextdata, setContextData } = manageContext(stemplate);
    // const [data, setData] = useState(props.data)
    const data = contextdata.consultation?.[contextdata.natureindex]?.NewData?.[props.index]?.editArray;
    const { parentClass } = props
    const [refresh, setRefresh] = useState(0)
    const [image, setImage] = useState(false)

    const weightindex = 1
    const heightindex = 0
    const bsaindex = 2


    function handleInputChange(text, index, field, details) {

        const updatedDetails = {
            ...details,
            EditFlag: details.EditFlag === 1 ? 2 : details.EditFlag === 3 ? 4 : details.EditFlag,
            [field]: text
        };

        // Clone the responseJSON to avoid direct mutation
        const updatedResponseJSON = {
            ...contextdata,
            editStatus: true,
            consultation: [...contextdata.consultation], // Clone the consultation array
        };

        // Ensure that the specific index and NewData array exist
        const natureindex = updatedResponseJSON.natureindex ?? 0;

        // Create a deep clone for the NewData and editArray structures

        updatedResponseJSON.consultation[natureindex] = {
            ...updatedResponseJSON.consultation[natureindex],
            editStatus: true,
            NewData: [...updatedResponseJSON.consultation[natureindex].NewData],
        };

        updatedResponseJSON.consultation[natureindex].NewData[props.index] = {
            ...updatedResponseJSON.consultation[natureindex].NewData[props.index],
            editArray: [...updatedResponseJSON.consultation[natureindex].NewData[props.index].editArray]
        }

        updatedResponseJSON.consultation[natureindex].NewData[props.index].editArray[index] = {
            ...updatedResponseJSON.consultation[natureindex].NewData[props.index].editArray[index],
            ...updatedDetails
        }

        if (index == heightindex) {

            if (isBNUL(data) && isNUQ(text) && isNUQ(data[weightindex]?.value)) {

                // const value = (data[weightindex].value / (text * text)) * 10000;
                const value = calculateSquareRoot(data[weightindex].value, text);
                const updatedField = value.toFixed(2);

                const updatedBmiDetails = {
                    ...data[bsaindex],
                    EditFlag: data[bsaindex].EditFlag === 1 ? 2 : data[bsaindex].EditFlag === 3 ? 4 : data[bsaindex].EditFlag,
                    value: updatedField
                };

                updatedResponseJSON.consultation[natureindex].NewData[props.index].editArray[bsaindex] = {
                    ...updatedResponseJSON.consultation[natureindex].NewData[props.index].editArray[bsaindex],
                    ...updatedBmiDetails
                }
            }
        }

        if (index == weightindex) {
            if (isBNUL(data) && isNUQ(data[heightindex]?.value) && isNUQ(text)) {

                // const value = (text / (data[heightindex].value * data[heightindex].value)) * 10000;
                const value = calculateSquareRoot(text, data[heightindex].value);
                const updatedField = value.toFixed(2);

                const updatedBmiDetails = {
                    ...data[bsaindex],
                    EditFlag: data[bsaindex].EditFlag === 1 ? 2 : data[bsaindex].EditFlag === 3 ? 4 : data[bsaindex].EditFlag,
                    value: updatedField
                };

                updatedResponseJSON.consultation[natureindex].NewData[props.index].editArray[bsaindex] = {
                    ...updatedResponseJSON.consultation[natureindex].NewData[props.index].editArray[bsaindex],
                    ...updatedBmiDetails
                }
            }
        }

        setContextData(updatedResponseJSON);
        // console.log('updatedResponseJSON..........', JSON.stringify(updatedResponseJSON));
        Global.EditStatus = 1;

    };

    return (
        <View style={{
            padding: normalize(5),
        }}>
            {isNU(data) ?

                <View style={{ backgroundColor: 'rgba(237, 232, 232,0.3)', borderWidth: 1, borderColor: 'lightgrey', padding: normalize(5), width: Dimensions.get('screen').width * 0.98 }}>
                    <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between' }}>
                        {parentClass.display != undefined && parentClass.display != "" ?
                            <View style={{ flexDirection: 'row', marginLeft: normalize(2), marginTop: normalize(5), alignItems: 'center' }}>
                                <Icons.FontAwesome5 name={"dot-circle"} size={normalize(10)} color="darkblue" />
                                <Text style={{ paddingLeft: normalize(10), fontWeight: 'bold', fontSize: normalize(14) }}>{parentClass.display}</Text>
                            </View> : null}

                        {/* INFO TAG */}
                        <TouchableOpacity onPress={() => setImage(!image)}
                            hitSlop={{ left: 10, right: 10, top: 10, bottom: 10 }}>
                            <Icons.AntDesign name={"infocirlce"} size={normalize(15)}
                                color="grey" style={{ paddingRight: normalize(10) }} />
                        </TouchableOpacity>
                    </View>

                    <View style={{ flexDirection: 'row', justifyContent: 'space-between', }}>
                        <STextInput
                            unit={"kg"}
                            data={{
                                value: data[weightindex]?.value,
                                type: 'number-pad',
                                itemwidth: Dimensions.get('screen').width * 0.25,
                                displaytext: "Weight",
                                minvalue: 0,
                                maxvalue: 500,
                                errorStatus: false
                            }}
                            callBack={val => (val == undefined ? null :
                                // data[weightindex].value = val,
                                // getEditFlag(data[weightindex]),
                                // setRefresh(refresh + 1)
                                handleInputChange(val, weightindex, 'value', data[weightindex])
                            )} />

                        <STextInput
                            unit={"cm"}
                            data={{
                                value: data[heightindex]?.value,
                                type: 'number-pad',
                                itemwidth: Dimensions.get('screen').width * 0.25,
                                displaytext: "Height",
                                minvalue: 10,
                                maxvalue: 250,
                                errorStatus: false
                            }}
                            callBack={val => (val == undefined ? null :
                                // data[heightindex].value = val, 
                                // getEditFlag(data[heightindex]), 
                                // setRefresh(refresh + 1)

                                handleInputChange(val, heightindex, 'value', data[heightindex])
                            )} />
                    </View>

                    {data != undefined && data[heightindex]?.value != undefined &&
                        data[weightindex]?.value != undefined && data[heightindex]?.value != ""
                        && data[weightindex]?.value != "" ?
                        <View style={{ flexDirection: 'row', justifyContent: 'center', paddingTop: normalize(10) }}>
                            <Text style={{ color: 'darkblue', fontWeight: 'bold', fontSize: normalize(16) }}>{" BSA = "}</Text>
                            <Text style={{ color: 'darkblue', fontWeight: 'bold', fontSize: normalize(16) }}>{data[bsaindex]?.value + "  m²"}</Text>
                        </View> : null}

                    {image ?
                        <View style={{ paddingHorizontal: normalize(5) }}>
                            <Image
                                style={{ width: '100%', height: normalize(200), resizeMode: 'stretch' }}
                                source={{ uri: "https://www.medindia.net/images/common/calculator/950_400/body-surface-area.jpg" }}
                            />
                        </View> : null}

                    {/* <View style={{
                borderWidth: 0.6,
                borderColor: 'grey',
                marginTop: normalize(10)
            }}>
            </View> */}
                </View>
                : null}
        </View>
    )

    function calculateSquareRoot(a, b) {
        const result = (a * b) / 3600;
        return Math.sqrt(result);
    }

    function getBSAValue() {
        if (ValueCheck(data) && ValueCheck(data[heightindex]?.value) && ValueCheck(data[weightindex]?.value)) {

            let bsa = calculateSquareRoot(data[weightindex]?.value, data[heightindex]?.value);

            // let bmi = (data[1].value / (data[0].value * data[0].value)) * 10000;

            data[bsaindex].value = (bsa).toFixed(2)
            getEditFlag(data[bsaindex])
        }
        return data[bsaindex]?.value + "  m²"
    }

    function getEditFlag(params) {
        if (params.EditFlag == 1) {
            params.EditFlag = 2
        } else if (params.EditFlag == 3) {
            params.EditFlag = 4
        }
        Global.EditStatus = 1
        contextdata.consultationEdit.editStatus = true
    }
}
