import React, { useState, useEffect, useContext, memo } from 'react';
import { Text, TextInput, StyleSheet, View, Image, TouchableWithoutFeedback, TouchableOpacity, Dimensions, ImageBackground, FlatList, Switch, Alert, ScrollView, } from 'react-native';
import { colors } from '../CommonStyle/commonStyle';
import ComponentStyles, { normalize } from '../CommonStyle/componentStyle';
import popupStyles, { getListviewItem, getListviewItemText, } from '../CommonStyle/PopupStyle';
import { Collapse, CollapseHeader, CollapseBody, } from 'accordion-collapse-react-native';
import Entypo from 'react-native-vector-icons/Entypo';
import InsureResponseComponentContext from '../Handlers/insureResponseComponentContext';
import AntDesign from 'react-native-vector-icons/AntDesign';
import FontAwesome5 from 'react-native-vector-icons/FontAwesome5';
import { APIURL } from '../Common/apiConstants';
import { ArrayCheck, CButtonShadow, CShadowDynamic, getLoading, isBNUL, isNU, isNUQ, notifyMessage, ValueCheck } from '../CommonStyle/ComponentFunctions';
import { Global } from '../Common/Global';
import Loader from '../Custom/Loader';
import NetworkServiceCall from '../Common/NetworkServiceCall';
import axios from 'axios'
import SSearchBar from '../StaticComponents/SSearchBar';
import SAlphabet from '../StaticComponents/SAlphabet';
import FastImage from 'react-native-fast-image';
import HOCIcons from '../HOC/HOCIcons';
import SDropDownHoc from '../StaticComponents/SDropDownHoc';
import CFooterView from './CFooterView';
import HShadowButton from '../HOC/HShadowButton';
import ABlink from '../Alerts/ABlink';
import CBackHandler from './CBackHandler';

function CIcdView(props) {

    const [isLoading, setIsLoading] = useState(false);
    const [data, setData] = useState(props.data)
    const [icdState, setIcdState] = useState({});
    const [icdOverlay, setIcdOverlay] = useState(false);
    const [icdOverlayData, setIcdOverlayData] = useState();
    const [deleteConfirmation, setDeleteConfirmation] = useState(false);
    const [deleteData, setDeleteData] = useState();
    const [edit, setEdit] = useState(false);

    useEffect(() => {
        getData()
    }, [])

    function getData() {

        setEdit(false);
        setIsLoading(true);

        let buttonapi = "http://122.15.161.229:9192/emr/emrcommonget/rnhomrpatientcharticd " + Global.PatientDetails.homrpatientchart;

        console.log('getData buttonapi',buttonapi);

        NetworkServiceCall("get", buttonapi, "")
            .then(function (response) {
                console.log('hihihi', JSON.stringify(response))
                if (isNU(response.httpstatus == 200) && isNU(response.data)) {

                    console.log('response.data.diagnosis', JSON.stringify(response.data.diagnosis));
                    setIcdState({
                        editflag: isBNUL(response.data.diagnosis) ? 2 : 1,
                        diagnosis: isBNUL(response.data.diagnosis) ? response.data.diagnosis : []
                    })
                    if(isBNUL(response.data.diagnosis)){
                        Global.PatientDetails.diagnosis = response.data.diagnosis
                    }
                    setIsLoading(false);
                }
                else {
                    setIsLoading(false);
                }
            })
    }

    function fnstring(i) {
        return isNU(i) ? i.toString() : null
    }

    function fnarray(i) {
        let array = [];
        isBNUL(i) ? i.map(data => { data.selected ? array.push(data.displayvalue) : null }) : null
        return array
    }

    function fnarraycode(i) {
        let array = [];
        isBNUL(i) ? i.map(data => { array.push(data.datavalue) }) : null
        return array
    }

    function getSave(params) {

        setIsLoading(true);

        const output = {
            "groups": {
                "procedurename": "homrpatientcharticd1",
                "homrpatientchart": Global.PatientDetails.homrpatientchart,
                "suuser": Global.userData.suuser,
                "hosuconsultant": Global.userData.hosuconsultant,
                "remarks": "",
                "editflag": icdState.editflag,
                "diagnosis": isNU(icdState) && isBNUL(icdState.diagnosis) ? icdState.diagnosis.map((val) => {

                    return {
                        ...val,
                        hosumrcode: isBNUL(val.icd) ? fnstring(fnarraycode(val.icd)) : ''
                    }

                }) : []

            }
        };
        const buttonapi = APIURL + 'commondelete/RnCommonDelete';
        console.log('output.......', JSON.stringify(output));

        NetworkServiceCall('post', buttonapi, output).then(function (response) {
            if (response.httpstatus == 200) {
                setIsLoading(false);
                getData();
                notifyMessage('Diagnosis Saved', 1);
            }
            else {
                setIsLoading(false);
                notifyMessage('Diagnosis Not Saved', 2);
            }
        })

    }

    function getFunction(val) {

        switch (val.functionid) {
            case 1:
                getSave();
                break;
            case 2:
                setIcdOverlayData({
                    diagnosisnature: 'P',
                    displaytext: 'PROVISIONAL DIAGNOSIS ICD',
                });
                setIcdOverlay(true);
                break;
            case 3:
                setIcdOverlayData({
                    diagnosisnature: 'F',
                    displaytext: 'PROVISIONAL DIAGNOSIS ICD',
                });
                setIcdOverlay(true);
                break;

            default:
                notifyMessage('Incorporate soon.', 1)
                break;
        }

    }

    function getProvOrFinalData(val) {

        switch (val) {
            case "P":
                var array = {
                    "icongroup": 5,
                    "iconname": 'stethoscope',
                    "diagnosisnature": "P",
                    "diagnosisname": "PROVISIONAL DIAGNOSIS",
                    "icd": []
                };
                return array;
            case "F":
                var array = {
                    "icongroup": 5,
                    "iconname": 'stethoscope',
                    "diagnosisnature": "F",
                    "diagnosisname": "FINAL DIAGNOSIS",
                    "icd": []
                };
                return array;
        }

    }

    function checkArrayisPresent(prevstate, type) {

        if (type == "P") {
            let arr = [...prevstate];
            if (arr.some(item => item.diagnosisnature == "P")) {
            }
            else {
                arr.push(getProvOrFinalData(icdOverlayData.diagnosisnature));
            }
            return arr;
        }
        else if (type == "F") {
            let arr = [...prevstate];
            if (arr.some(item => item.diagnosisnature == "F")) {
            }
            else {
                arr.push(getProvOrFinalData(icdOverlayData.diagnosisnature));
            }
            return arr;
        }
        else {
            return [getProvOrFinalData(icdOverlayData.diagnosisnature)]
        }
    }

    function fnDeleteItem(params) {

        setIcdState(prevstate => {
            const updatejson = {
                ...prevstate,
                diagnosis: [...prevstate.diagnosis]
            };

            updatejson.diagnosis = updatejson.diagnosis.map((val) => {
                return val.diagnosisnature == params.diagnosisnature ?
                    {
                        ...val,
                        icd: val.icd.filter((val2) => val2.datavalue != params.datavalue)
                    } : { ...val }
            })


            return updatejson
        });
        setEdit(true);

    }

    function icdView(val, prevdata) {

        return (
            <TouchableWithoutFeedback>
                <View style={{ borderWidth: 0.5, borderColor: 'lightblue', backgroundColor: 'white', flexDirection: 'row', justifyContent: 'flex-start', alignItems: 'center', padding: normalize(7) }}>
                    <HOCIcons.Icons
                        color={Global.AppTheme.primary_color}
                        icongroup={3}
                        name={'virus'}
                        size={normalize(15)}
                        style={{
                            marginRight: normalize(7)
                        }}
                    />
                    <View style={{ flex: 1, borderWidth: 0 }}>
                        <Text style={{ color: 'black', fontWeight: 'bold', fontSize: normalize(14) }}>{isNU(val.displayvalue) ? val.displayvalue : ''}</Text>
                    </View>
                    <TouchableOpacity
                        onPress={() => {
                            setDeleteData({
                                ...val,
                                diagnosisnature: prevdata.diagnosisnature
                            });
                            setDeleteConfirmation(true);
                        }}
                    >
                        <HOCIcons.Icons
                            color={'#cc2323'}
                            icongroup={3}
                            name={'delete'}
                            size={normalize(20)}
                            style={{
                                marginHorizontal: normalize(5)
                            }}
                        />
                    </TouchableOpacity>
                </View>
            </TouchableWithoutFeedback>
        )

    }

    return (
        <View style={{ flex: 1, borderWidth: 0, width: '100%' }}>
            <Text style={{ alignSelf: 'center', fontSize: normalize(10), fontWeight: 'bold', marginBottom: normalize(5), marginTop: normalize(-5) }}>{ValueCheck(data.heading) ? (data.heading).toUpperCase() : data.heading}</Text>
            <View style={{ flex: 1, borderWidth: 0, width: '100%' }}>
                {
                    isNU(icdState) && isBNUL(icdState.diagnosis) ?
                        <ScrollView style={{ marginTop: normalize(10) }}>
                            {icdState.diagnosis.map((val, i) => {
                                return (
                                    <>
                                        {isBNUL(val.icd) ?
                                            <>
                                                <View style={{ padding: normalize(7), borderWidth: 0.5, flexDirection: 'row', alignItems: 'center', borderRadius: 1, borderColor: 'lightgrey', backgroundColor: '#f0f0f0', ...CShadowDynamic(-3, 1, 5, -2, Global.AppTheme.primary_color) }}>
                                                    <HOCIcons.Icons
                                                        size={normalize(15)}
                                                        icongroup={val.icongroup ? val.icongroup : 5}
                                                        name={val.iconname ? val.iconname : 'user-md'}
                                                        color={Global.AppTheme.primary_color}
                                                        style={{
                                                            marginRight: normalize(7),
                                                            textAlign: 'center',
                                                        }}
                                                    />
                                                    <Text style={{ fontSize: normalize(15), fontWeight: 'bold', color: Global.AppTheme.primary_color }}>{val.diagnosisname ? val.diagnosisname : null}</Text>
                                                </View>
                                                {isBNUL(val.icd) ?
                                                    <View style={{ borderWidth: 0 }}>
                                                        {val.icd.map((val2) => {
                                                            return (
                                                                icdView(val2, val)
                                                            )
                                                        })}
                                                    </View>
                                                    : null}
                                            </>
                                            : null}
                                    </>
                                )
                            })}
                        </ScrollView>

                        :
                        <View style={{ borderWidth: 0, justifyContent: 'center', alignItems: 'center', flex: 1 }}>
                            {/* <ABlink> */}
                            <View style={{ flexDirection: 'row', alignItems: 'center' }}>
                                <HOCIcons.Icons
                                    icongroup={10}
                                    size={normalize(18)}
                                    name={'info'}
                                    color={'grey'}
                                    style={{ paddingHorizontal: normalize(5) }}
                                />
                                <Text style={{ textAlign: 'center', color: Global.AppTheme.primary_color, fontSize: normalize(15), fontWeight: 'bold' }} >{"Select provisional or final diagnosis ICD."}</Text>
                            </View>
                            {/* </ABlink> */}
                        </View>
                }
                {icdOverlay && isNU(icdOverlayData) && isNU(icdOverlayData.diagnosisnature) ?
                    <SDropDownHoc
                        overlayheading={icdOverlayData.displaytext ? icdOverlayData.displaytext : ''}
                        setoverlay={val => {
                            setIcdOverlay(false);
                        }}
                        overlay={true}
                        heading={'Add'}
                        fastselection={true}
                        multiselect={true}
                        buttonstyle={{

                        }}
                        overlaystyle={{
                            borderRadius: 20,
                            height: Dimensions.get('window').height * 0.6,
                            borderWidth: 5,
                            borderColor: '#4497ea'
                        }}
                        height={0.12}
                        dropdownapi={APIURL + 'emr/emrcommonget/rnfavoriteicd ' + Global.userData.hosuconsultant}
                        setcustomstage={3}
                        natureoption={false}
                        disableApiCall={true}
                        arraycallback={value => {

                            setIcdState(prevstate => {

                                const updatedata = {
                                    ...prevstate,
                                    diagnosis: isNU(prevstate) && isBNUL(prevstate.diagnosis) ? checkArrayisPresent(prevstate.diagnosis, icdOverlayData.diagnosisnature) : [getProvOrFinalData(icdOverlayData.diagnosisnature)] // checkArrayisPresent(prevstate.diagnosis, icdOverlayData.diagnosisnature)
                                };
                                updatedata.diagnosis = updatedata.diagnosis.map((val) => {

                                    if (val.diagnosisnature == icdOverlayData.diagnosisnature) {
                                        if (isBNUL(val.icd)) {
                                            const duplicateItems = value.filter(icdItem =>
                                                val.icd.some(existingItem => existingItem.datavalue === icdItem.datavalue)
                                            );
                                            if (duplicateItems.length > 0) {
                                                notifyMessage(`${fnstring(fnarray(duplicateItems))} is already present.`, 1);
                                            }
                                        }
                                        return {
                                            ...val,
                                            icd: [
                                                ...val.icd,
                                                ...value.filter(icdItem => !val.icd.some(existingItem => existingItem.datavalue === icdItem.datavalue))
                                            ]
                                        }
                                    }
                                    else {
                                        return { ...val }
                                    }
                                });
                                return updatedata;
                            });
                            setEdit(true);

                        }}
                        iconclose={{
                            "icongroup": 3,
                            "name": 'close-circle',
                            "color": Global.AppTheme.primary_color,
                            "size": normalize(15),
                            "style": {
                                paddingHorizontal: normalize(5)
                            }
                        }}
                        iconclosecallback={k => {

                        }}
                        icd={true}
                        stage={true}
                        hideselectarray={true}
                        selectarray={[
                            {
                                icongroup: 4,
                                iconname: 'heartbeat',
                                displayvalue: 'Favorite',
                                color: '#c70eed',
                                shadowcolor: '#f1d4f7',
                                stage: 1,
                                visibility: true,
                            },
                            {
                                icongroup: 4,
                                iconname: 'list-ul',
                                displayvalue: 'ALL',
                                color: 'blue',
                                shadowcolor: '#c9d7ff',
                                stage: 3,
                                visibility: true,
                            }
                        ]}
                    />
                : null}
            </View>
            <CFooterView>
                <View style={{ flexDirection: 'row', justifyContent: 'flex-start' }}>
                    {[
                        {
                            icongroup: 4,
                            iconname: 'save',
                            iconcolor: 'red',
                            displaytext: 'SAVE',
                            functionid: 1,
                            visibility: edit && isNU(icdState) && isNU(icdState.editflag) && isBNUL(icdState.diagnosis) ? true : false,
                        },
                        {
                            icongroup: 5,
                            iconname: 'stethoscope',
                            iconcolor: Global.AppTheme.primary_color,
                            displaytext: 'PROVISIONAL DIAGNOSIS',
                            functionid: 2,
                            visibility: isNU(icdState) && isNU(icdState.editflag) ? true : false,
                        },
                        {
                            icongroup: 5,
                            iconname: 'diagnoses',
                            iconcolor: Global.AppTheme.primary_color,
                            displaytext: 'FINAL DIAGNOSIS',
                            functionid: 3,
                            visibility: isNU(icdState) && isNU(icdState.editflag) ? true : false,
                        }
                    ].map((val) => {
                        return (
                            val.visibility ?
                                <View style={{ borderWidth: 0, marginLeft: normalize(5) }}>
                                    <HShadowButton
                                        useicon={true}
                                        usetext={true}
                                        buttonstyle={{
                                            margin: normalize(5),
                                            borderLeftWidth: 0,
                                            borderBottomWidth: 0,
                                            borderRadius: 5,
                                            borderWidth: 0,
                                            borderColor: Global.AppTheme.primary_color,
                                            justifyContent: 'center',
                                            alignItems: 'center',
                                            backgroundColor: 'white',
                                            height: normalize(45),
                                            width: normalize(55),
                                            ...CButtonShadow(),
                                        }}
                                        icongroup={val.icongroup}
                                        iconcolor={val.iconcolor}
                                        iconname={val.iconname}
                                        iconsize={normalize(20)}
                                        iconstyle={{ textAlign: 'center', borderWidth: 0, marginVertical: normalize(5) }}
                                        displaytext={val.displaytext}
                                        buttonCallback={() => {
                                            getFunction(val)
                                        }}
                                        numberOfLines={2}
                                        textstyle={{
                                            color: val.iconcolor,
                                            fontSize: normalize(8),
                                            textAlign: 'center',
                                            fontWeight: 'bold',
                                            lineHeight: normalize(8)
                                        }}
                                    />
                                </View>
                                : null
                        )
                    })}
                </View>
            </CFooterView>
            {isLoading ? <Loader displaytext={true} /> : null}
            {deleteConfirmation && isNU(deleteData) ? (
                <CBackHandler
                    type={8} // 4 for deletion
                    callBack={(val) => {
                        setDeleteConfirmation(false)
                        fnDeleteItem(deleteData)
                    }}
                    close={(val) => (val == undefined ? null : setDeleteConfirmation(false))}
                    displaytext={`${'Are you sure you want to delete '}${deleteData.displayvalue}${' ?'}`}
                    displaybuttons={{
                        "iconname": "trash",
                        "button1": "No",
                        "button2": "Yes",
                        "heading": "DELETION"
                    }}
                />
            ) : null}
        </View>
    );
}

export default CIcdView;
