import React, { memo, useState } from 'react';
import { View, TextInput } from 'react-native';
import { isNU } from '../CommonStyle/ComponentFunctions';
import CText from './CText';
import HOCIcons from '../HOC/HOCIcons';
import { normalize } from '../CommonStyle/componentStyle';

const CTextInput = (props) => {

    const [text, setText] = useState("")
    const [data, setData] = useState(props.data != undefined ? props.data : {
        itemwidth: "100%",
        displaytext: "Name",
        iconname: 'home',
        value: 45,
        type: 'number-pad',
        editable: true,
        placeholder: "Name",
        decimal: 2,
        icongroup: 5
    });

    return (
        <View style={{ borderWidth: 0, width: data.itemwidth != undefined ? data.itemwidth : '100%' }}>
            {data.displaytext != undefined ?
                <CText style={{ fontSize: data.dtextsize != undefined ? data.dtextsize : normalize(11), color: 'black', paddingHorizontal: 5, textAlign: data.alignment != undefined ? data.alignment : 'left', fontWeight: data.dfontweight ? data.dfontweight : 'normal' }}>{data.displaytext != undefined ? data.displaytext : "Default"}</CText> : null}
            <View style={{ flexDirection: 'row', borderWidth: isNU(props.CBorderWidth) ? props.CBorderWidth : 1, borderColor: 'lightgrey', borderRadius: 10, alignItems: 'center', height: props.CCommonHeight != undefined ? props.CCommonHeight : normalize(35) }}>
                {data.disableicon ?
                    null :

                    <HOCIcons.Icons
                        icongroup={data.icongroup != undefined ? data.icongroup : 5}
                        name={data.iconname != undefined ? data.iconname : "file-alt"}
                        size={data.iconsize != undefined ? data.iconsize : normalize(15)}
                        color={data.iconcolor != undefined ? data.iconcolor : "darkblue"}
                        style={{ paddingHorizontal: 5 }}
                        onPress={() => { props.CIconCallBack != undefined ? props.CIconCallBack(data) : null }}
                    />
                }
                <TextInput
                    style={{ borderWidth: 0, flex:1, paddingRight: normalize(5), fontSize: normalize(14), height: data.textarea != undefined ? normalize(60) : normalize(35), color: 'black' }}
                    onChangeText={val => { setText(val), props.callBack != undefined ? props.callBack(val) : null }}
                    autoCapitalize={data.capitalize != undefined ? data.capitalize : 'none'}
                    textAlign={data.alignment != undefined ? data.alignment : data.type == 'number-pad' ? 'left' : 'left'}
                    keyboardType={data.type != undefined ? data.type : 'default'}
                    maxLength={data.maxlength != undefined ? data.maxlength : 200}
                    editable={isNU(props.editable) ? props.editable : data.editable != undefined ? data.editable : true}
                    multiline={data.textarea != undefined ? data.textarea : false}
                    numberOfLines={data.textarea != undefined ? 8 : 1}
                    placeholder={data.placeholder != undefined ? data.placeholder : null}
                    {...props}
                >
                    {data.value != undefined ?
                        data.value : ""}
                </TextInput>
            </View>
        </View>
    )
}
export default memo(CTextInput);