import React, { useState, useContext, useEffect, useRef } from 'react'
import { View, Text, TouchableOpacity, FlatList, Dimensions, Image, ActivityIndicator, StyleSheet } from 'react-native'
import { Global } from '../../Common/Global'
import Icons from '../../Common/Icons'
import { isBNUL, isNU, isNUQ, isNUQZ, ValueCheck } from '../../CommonStyle/ComponentFunctions'
import { normalize } from '../../CommonStyle/componentStyle'
import EmrResponseComponentContext from '../../Handlers/emrResponseComponentContext'
import STextInput from '../../StaticComponents/STextInput'
import { useNavigation } from '@react-navigation/native'
import STemplateContext from '../../Handlers/sTemplateContext'
import { manageContext } from '../../Handlers/manageContext'
import { APIURL } from '../../Common/apiConstants'
import CLineChart from './CLineChart'

export default function CBMI(props) {

    const navigation = useNavigation();
    const { responseJSON, setResponseJSON } = useContext(EmrResponseComponentContext);
    const stemplate = props.stemplate ?? false;
    const { contextdata, setContextData } = manageContext(stemplate);

    const data = contextdata?.consultation?.[contextdata.natureindex]?.NewData?.[props.index]?.editArray;
    // const data = responseJSON.consultation?.[responseJSON.natureindex]?.NewData?.[props.index]?.editArray;
    //   const [data, setData] = useState(props.data)


    const { parentClass } = props
    const [refresh, setRefresh] = useState(0)
    const [image, setImage] = useState(false);
    const [itemindex, setItemIndex] = useState(0);
    const isInitialMount = useRef(true);

    // --- NEW STATE FOR CHART DISPLAY ---
    const [historicalData, setHistoricalData] = useState(null);
    const [selectedItem, setSelectedItem] = useState(null);
    const [isLoading, setIsLoading] = useState(false);
    // -----------------------------------

    const patientDatalistId = Global.PatientDetails?.datalistid
    const apiUrlBase = APIURL + 'bldget/invcommonget/rnbbvitalchart';

    const fetchChartData = async (item) => {
        setIsLoading(true);
        setSelectedItem(item);
        setHistoricalData(null);

        const vitalName = item.displaytext.toLowerCase().replace(/\s/g, '');

        // Correct API URL construction: /rnbbvitalchart{space}ID,vitalName
        const apiUrl = `${apiUrlBase} ${patientDatalistId},${vitalName}`;

        console.log("Fetching chart data for vital:", item.displaytext, "from URL:", apiUrl);

        let chartData = [];

        try {
            const response = await fetch(apiUrl);
            const jsonResponse = await response.json();

            if (jsonResponse.success && jsonResponse.data && jsonResponse.data.data) {
                chartData = jsonResponse.data.data;
                setHistoricalData(chartData);
            } else {
                setHistoricalData([]);
            }

        } catch (error) {
            console.error(`Error fetching vital chart data for ${item.displaytext}:`, error);
            setHistoricalData([]);
        } finally {
            setIsLoading(false);
        }
    };

    const weightindex = 0
    const heightindex = 1
    const bmiindex = 2

    // useEffect(() => {

    //     if (isInitialMount.current) {
    //         isInitialMount.current = false;
    //         return;
    //     }

    //     const updateContext = {
    //         ...responseJSON,
    //         consultationEdit: {
    //             ...responseJSON.consultationEdit,
    //             NewData: [...responseJSON.consultationEdit.NewData], // Create a copy of the array
    //             editStatus: true,
    //         },
    //     };

    //     updateContext.consultationEdit.NewData[props.index] = {
    //         ...updateContext.consultationEdit.NewData[props.index],
    //         editArray: [...updateContext.consultationEdit.NewData[props.index].editArray], // Create a copy of editArray
    //     };

    //     updateContext.consultationEdit.NewData[props.index].editArray[itemindex] = data[itemindex];

    //     setResponseJSON(updateContext);
    //     props.revCallback(updateContext);

    // }, [data, itemindex]);

    // useEffect(() => {

    //     if (isInitialMount.current) {
    //         isInitialMount.current = false;
    //         return;
    //     }

    //     getBMIValue()

    // }, [data[2].value, data[0].value]);

    function handleInputChange(text, index, field, details) {

        const updatedDetails = {
            ...details,
            EditFlag: details.EditFlag === 1 ? 2 : details.EditFlag === 3 ? 4 : details.EditFlag,
            [field]: text
        };

        // Clone the responseJSON to avoid direct mutation
        const updatedResponseJSON = {
            ...contextdata,
            editStatus: true,
            consultation: [...contextdata.consultation], // Clone the consultation array
        };

        // Ensure that the specific index and NewData array exist
        const natureindex = updatedResponseJSON.natureindex ?? 0;

        // Create a deep clone for the NewData and editArray structures

        updatedResponseJSON.consultation[natureindex] = {
            ...updatedResponseJSON.consultation[natureindex],
            editStatus: true,
            NewData: [...updatedResponseJSON.consultation[natureindex].NewData],
        };

        updatedResponseJSON.consultation[natureindex].NewData[props.index] = {
            ...updatedResponseJSON.consultation[natureindex].NewData[props.index],
            editArray: [...updatedResponseJSON.consultation[natureindex].NewData[props.index].editArray]
        }

        updatedResponseJSON.consultation[natureindex].NewData[props.index].editArray[index] = {
            ...updatedResponseJSON.consultation[natureindex].NewData[props.index].editArray[index],
            ...updatedDetails
        }

        if (index == heightindex) {

            if (isBNUL(data) && isNUQ(text) && isNUQ(data[weightindex].value)) {

                const value = (data[weightindex].value / (text * text)) * 10000;
                const updatedField = value.toFixed(3);

                const updatedBmiDetails = {
                    ...data[bmiindex],
                    EditFlag: data[bmiindex].EditFlag === 1 ? 2 : data[bmiindex].EditFlag === 3 ? 4 : data[bmiindex].EditFlag,
                    value: updatedField
                };

                updatedResponseJSON.consultation[natureindex].NewData[props.index].editArray[bmiindex] = {
                    ...updatedResponseJSON.consultation[natureindex].NewData[props.index].editArray[bmiindex],
                    ...updatedBmiDetails
                }
            }
        }

        if (index == weightindex) {
            if (isBNUL(data) && isNUQ(data[heightindex].value) && isNUQ(text)) {
                const value = (text / (data[heightindex].value * data[heightindex].value)) * 10000;
                const updatedField = value.toFixed(3);

                const updatedBmiDetails = {
                    ...data[bmiindex],
                    EditFlag: data[bmiindex].EditFlag === 1 ? 2 : data[bmiindex].EditFlag === 3 ? 4 : data[bmiindex].EditFlag,
                    value: updatedField
                };

                updatedResponseJSON.consultation[natureindex].NewData[props.index].editArray[bmiindex] = {
                    ...updatedResponseJSON.consultation[natureindex].NewData[props.index].editArray[bmiindex],
                    ...updatedBmiDetails
                }
            }
        }


        setContextData(updatedResponseJSON);
        // setResponseJSON(updatedResponseJSON);
        // console.log('updatedResponseJSON..........', JSON.stringify(updatedResponseJSON));
        Global.EditStatus = 1;

    };

    return (
        <View style={{
            padding: normalize(5),
        }}>
            <View style={{ backgroundColor: 'rgba(237, 232, 232,0.3)', borderWidth: 1, borderColor: 'lightgrey', padding: normalize(5), width: Dimensions.get('screen').width * 0.98 }}>
                <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between' }}>
                    {parentClass.display != undefined && parentClass.display != "" ?
                        <View style={{ flexDirection: 'row', marginLeft: normalize(2), marginTop: normalize(5), alignItems: 'center' }}>
                            <Icons.FontAwesome5 name={"dot-circle"} size={normalize(10)} color="darkblue" />
                            <Text style={{ paddingLeft: normalize(10), fontWeight: 'normal', fontSize: normalize(14) }}>{parentClass.display}</Text>
                        </View> : null}

                    {/* INFO TAG */}
                    <TouchableOpacity onPress={() => setImage(!image)}
                        hitSlop={{ left: 10, right: 10, top: 10, bottom: 10 }}>
                        <Icons.AntDesign name={"infocirlce"} size={normalize(15)}
                            color="grey" style={{ paddingRight: normalize(10) }} />
                    </TouchableOpacity>
                </View>

                <View style={{ flexDirection: 'row', justifyContent: 'space-between', }}>
                    <View style={{ justifyContent: 'center' }}>
                        <STextInput
                            unit={"kg"}
                            data={{
                                value: isNU(data) ? data[weightindex].value : null,
                                type: 'number-pad',
                                itemwidth: Dimensions.get('screen').width * 0.25,
                                displaytext: "Weight",
                                minvalue: 0,
                                maxvalue: 500,
                                errorStatus: false
                            }}
                            callBack={val => (val == undefined ? null :
                                (
                                    handleInputChange(val, weightindex, 'value', data[weightindex])
                                )
                            )}
                            tprcallback={(val) => {
                                console.log('tprcallback');
                                navigation.navigate('CTprVitalsign', {
                                    data: data[weightindex]
                                });
                            }}
                        />
                        <TouchableOpacity
                            style={{
                                position: 'absolute',
                                right: 0,
                                top: normalize(2),
                                paddingHorizontal: normalize(10),
                                paddingVertical: normalize(2),
                                justifyContent: 'center',
                                alignItems: 'center',
                            }}
                            onPress={() => {
                                fetchChartData({ displaytext: "Weight", unit: "kg" });
                            }}
                        >
                            <Icons.FontAwesome5
                                name="chart-line"
                                size={normalize(18)}
                                color="darkblue"
                            />
                        </TouchableOpacity>
                    </View>

                    <View style={{ justifyContent: 'center' }}>
                        <STextInput
                            unit={"cm"}
                            data={{
                                value: isNU(data) ? data[heightindex].value : null,
                                type: 'number-pad',
                                itemwidth: Dimensions.get('screen').width * 0.25,
                                displaytext: "Height",
                                minvalue: 10,
                                maxvalue: 250,
                                errorStatus: false
                            }}
                            callBack={val => (val == undefined ? null : (

                                // handleInputChange(val, 0, 'value', 'EditFlag')
                                handleInputChange(val, heightindex, 'value', data[heightindex])
                                //   getBMIValue()
                                // data[0].value = val, 
                                // getEditFlag(data[0]), 
                                // setRefresh(refresh + 1)
                            )
                            )}
                            tprcallback={(val) => {
                                console.log('tprcallback');
                                navigation.navigate('CTprVitalsign', {
                                    data: data[heightindex]
                                });
                            }}
                        />
                        <TouchableOpacity
                            style={{
                                position: 'absolute',
                                right: 0,
                                top: normalize(2),
                                paddingHorizontal: normalize(10),
                                paddingVertical: normalize(2),
                                justifyContent: 'center',
                                alignItems: 'center',
                            }}
                            onPress={() => {
                                fetchChartData({ displaytext: "Height", unit: "cm" });
                            }}
                        >
                            <Icons.FontAwesome5
                                name="chart-line"
                                size={normalize(18)}
                                color="darkblue"
                            />
                        </TouchableOpacity>
                    </View>
                </View>

                {isBNUL(data) && isNUQ(data[heightindex].value) && isNUQ(data[weightindex].value) && isNUQ(data[bmiindex].value) ?
                    <View style={{ flexDirection: 'row', justifyContent: 'space-evenly', paddingTop: normalize(10) }}>
                        <Text style={{ color: 'darkblue', fontWeight: 'bold', fontSize: normalize(16) }}>{"BMI"}</Text>
                        <Text style={{ color: 'darkblue', fontWeight: 'bold', fontSize: normalize(16) }}>{data[bmiindex].value + "  kg/m2"}</Text>
                    </View> : null}

                {image ?
                    <View style={{ paddingHorizontal: normalize(5) }}>
                        <Image
                            style={{ width: '100%', height: normalize(200), resizeMode: 'stretch' }}
                            source={{ uri: "https://media.istockphoto.com/id/1316804484/vector/man-bmi-body-mass-index-infographics-for-male-with-normal-weight-and-obesity-fat-and-skinny.jpg?s=612x612&w=0&k=20&c=xHeQFab35d3GQCpstV9OTUiAm5J_PQflju9fniHmgv8=" }}
                        />
                    </View> : null}
            </View>
            {/* --- CONDITIONAL CHART DISPLAY AREA --- */}
            {(isLoading || historicalData !== null) && (
                <View style={styles.chartContainer}>
                    {isLoading ? (
                        <ActivityIndicator size="large" color="darkblue" style={{ padding: normalize(20) }} />
                    ) : selectedItem && historicalData !== null && historicalData.length > 0 ? (
                        <>
                            <Text style={styles.chartTitle}>
                                {selectedItem.displaytext} Trend ({selectedItem.unit})
                            </Text>
                            <CLineChart data={historicalData} />
                        </>
                    ) : selectedItem ? (
                        <Text style={styles.noDataText}>No historical data available for {selectedItem.displaytext}.</Text>
                    ) : null}
                </View>
            )}
            {/* -------------------------------------- */}
        </View>
    )

    function getBMIValue() {

        if (isBNUL(data) && isNUQ(data[0].value) && isNUQ(data[2].value)) {
            const value = (data[2].value / (data[0].value * data[0].value)) * 10000;
            const updatedField = value.toFixed(3);
            //   handleInputChange(updatedField, 1, 'value', 'EditFlag', data[1])
        }

        // if (ValueCheck(data) && ValueCheck(data[0].value) && ValueCheck(data[2].value)) {
        //     let bmi = (data[2].value / (data[0].value * data[0].value)) * 10000;
        //     data[1].value = (bmi).toFixed(3)
        //     getEditFlag(data[1])
        // }
        // return data[1].value + "  kg/m2"
    }

    function getEditFlag(params) {
        if (params.EditFlag == 1) {
            params.EditFlag = 2
        } else if (params.EditFlag == 3) {
            params.EditFlag = 4
        }
        Global.EditStatus = 1
        responseJSON.consultationEdit.editStatus = true
    }
}

const styles = StyleSheet.create({
    chartContainer: {
        marginTop: normalize(10),
        padding: normalize(5),
        backgroundColor: 'rgba(237, 232, 232,0.3)',
        borderWidth: 1,
        borderColor: 'lightgrey',
        width: Dimensions.get('screen').width * 0.98
    },
    chartTitle: {
        fontSize: normalize(16),
        fontWeight: 'bold',
        color: 'darkblue',
        padding: normalize(5),
        marginBottom: normalize(5),
    },
    noDataText: {
        padding: normalize(15),
        textAlign: 'center',
        color: 'red',
        fontSize: normalize(14),
    }
});
