import React, { useState } from 'react';
import { View, TouchableOpacity, Platform, Dimensions, Text } from 'react-native';
import DateTimePicker from '@react-native-community/datetimepicker';
import CText from '../CustomComponents/CText';
import FontAwesome5 from 'react-native-vector-icons/FontAwesome5';
import { normalize } from '../CommonStyle/componentStyle';
import moment from 'moment';
import { Global } from '../Common/Global';
import { isNU, ValueCheck } from '../CommonStyle/ComponentFunctions';
import HOCIcons from '../HOC/HOCIcons';

export default function SDatePickerNew(props) {
  
  const [data, setData] = useState(props.data != undefined ? props.data : {})
  const [date, setDate] = useState(props.passingDate != undefined ? new Date(props.passingDate) : new Date());
  const [minimumdate, setMinimumDate] = useState(isNU(props.minimumdate) ? new Date(props.minimumdate) : new Date());
  const [mode, setMode] = useState('date');
  const [show, setShow] = useState(false);

  // console.log("LLLLLLLL IIIIIIIII UUUUUUUUUUU",JSON.stringify(props.data))

  

  const onChange = (event, selectedDate) => {

    console.log('onChange',event,selectedDate)

    setShow(Platform.OS === 'ios');

    if (event && event.type == "set") {

      // if (isNU(props.checkifdatematches)) {
      // }

      const currentDate = selectedDate || date;
      setDate(currentDate);
      setData({ ...data, ['value']: currentDate });
      console.log('currentDate',currentDate)
      props.onChangeData(currentDate);

      console.log('onChangeData', currentDate);
    }

  };

  const showMode = (currentMode) => {
    setShow(true);
    setMode(currentMode);
  };

  const showDatepicker = () => {
    showMode('date');
  };

  return (
    <View style={{
    }}>
      <View style={{
        width: data.itemwidth != undefined ? data.itemwidth : Dimensions.get('screen').width * 0.5,
        borderWidth: 0
      }}>
        {props.disableplaceholder && isNU(props.table) ?
          <Text
            style={{
              borderWidth: 0,
              fontSize: normalize(9),
              color: 'black'
            }}
          >
            {data.displaytext != undefined ? data.displaytext : "Date"}
          </Text>
        : null}
        <TouchableOpacity
          disabled={props.disabled ? true : false}
          onPress={() => showDatepicker()}
          style={props.pickerstyle ?
            props.pickerstyle :
            {
              flexDirection: 'row',
              backgroundColor: '#fff',
              width: ValueCheck(props.width) ? props.width : null,
              borderColor: 'lightgrey',
              borderWidth: props.table != undefined && props.table != true ? 1 : 0,
              borderRadius: 5,
              alignItems: 'center',
              height: normalize(30),
              elevation: props.table != undefined && props.table != true ? 3 : 0,
              justifyContent: props.table != undefined && props.table != true ? 'flex-start' : 'flex-start'
            }}
        >
          {props.icon ?
            <HOCIcons.Icons
              icongroup={isNU(props.icon.icongroup) ? props.icon.icongroup : 5}
              name={props.icon.name}
              size={props.icon.size}
              style={props.iconstyle}
            />
            :
            <FontAwesome5
              name={"calendar-alt"}
              size={normalize(15)}
              color={Global.AppTheme.primary_color}
              style={{ width: normalize(25) }}
            />
          }
          <Text style={props.textstyle ? props.textstyle : { fontSize: normalize(14), color: "black", fontWeight: 'bold' }}>
            {moment(date).format("DD-MM-YYYY")}
          </Text>
        </TouchableOpacity>
      </View>
      {show && (
        <DateTimePicker
          minimumDate={isNU(props.minimumdate) ? minimumdate : date}
          testID={"dateTimePicker"}
          value={date}
          mode={'date'}
          is24Hour={true}
          display="default"
          onChange={onChange}
        />
      )}
    </View>
  );
};