import React, { useState, useEffect } from 'react';
import {
  Modal,
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  ActivityIndicator,
  Alert,
} from 'react-native';
import OtpTextInput from '../Custom/OtpTextInput';
import { notifyMessage } from '../CommonStyle/ComponentFunctions';
import { Global } from '../Common/Global';
import Icons from '../Common/Icons';

const OTP_EXPIRY_TIME = 600;
const TEST_MODE = false;

const OTPVerificationModal = ({
  isVisible,
  onClose,
  onVerified,
  mobileNumber,
  donorName
}) => {
  const [otp, setOtp] = useState('');
  const [generatedOtp, setGeneratedOtp] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSendingOtp, setIsSendingOtp] = useState(false);
  const [timer, setTimer] = useState(OTP_EXPIRY_TIME);
  const [canResend, setCanResend] = useState(false);

  useEffect(() => {
    if (isVisible) {
      sendOTP();
      setTimer(OTP_EXPIRY_TIME);
      setCanResend(false);
      setOtp('');
    }
  }, [isVisible]);

  useEffect(() => {
    let interval;
    if (isVisible && timer > 0) {
      interval = setInterval(() => {
        setTimer((prev) => {
          if (prev <= 1) {
            setCanResend(true);
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isVisible, timer]);

  const generateOTP = () => {
    return Math.floor(1000 + Math.random() * 9000).toString();
  };

  const sendOTP = async () => {
    setIsSendingOtp(true);
    try {
      let newOtp;

      if (TEST_MODE) {
        newOtp = "2255";
        console.log("🔐 [TEST MODE] Using OTP:", newOtp);
      } else {
        newOtp = generateOTP();
        console.log("🔐 [LIVE MODE] Generated OTP:", newOtp);

        const apiUrl = `https://thesmsbuddy.com/api/v1/sms/send?key=saNaMKzZFU9BXNz6XFY8TrugYEHTrwuG&type=1&to=${mobileNumber}&sender=AMALAH&message=${newOtp}%20is%20the%20One%20Time%20Password%20(OTP)%20for%20your%20login%20to%20the%20Amala%20OTP%20is%20valid%20for%20next%2010%20minutes.%20Please%20do%20not%20share%20it%20with%20anyone.%20-%20Amala%20Hospital&flash=0&template_id=1207167263622963650`;

        const response = await fetch(apiUrl);
        const result = await response.json();

        if (!(result.status === "success" || response.ok)) {
          throw new Error("Failed to send OTP");
        }
      }

      setGeneratedOtp(newOtp);
      setTimer(OTP_EXPIRY_TIME);
      setCanResend(false);
      notifyMessage(`Code sent to ${mobileNumber}`, 2);
    } catch (error) {
      console.error("❌ Error sending OTP:", error);
      Alert.alert("Error", "Failed to send OTP. Please try again.");
    } finally {
      setIsSendingOtp(false);
    }
  };

  const handleOtpCallback = (enteredOtp) => {
    setOtp(enteredOtp);
    if (enteredOtp.length === 4) {
      handleVerifyOTP(enteredOtp);
    }
  };

  const handleVerifyOTP = (otpToVerify = otp) => {
    if (otpToVerify.length !== 4) {
      Alert.alert('Invalid OTP', 'Please enter the complete 4-digit code');
      return;
    }

    if (timer <= 0) {
      Alert.alert('OTP Expired', 'Please request a new code.');
      return;
    }

    setIsLoading(true);

    setTimeout(() => {
      if (otpToVerify === generatedOtp) {
        setIsLoading(false);
        notifyMessage('Verified successfully!', 3);
        onVerified();
        // handleClose(); // Don't call handleClose here as it triggers onClose (cancellation) logic
      } else {
        setIsLoading(false);
        Alert.alert('Invalid OTP', 'Please check and try again.');
        setOtp('');
      }
    }, 400);
  };

  const handleResendOTP = () => {
    setOtp('');
    sendOTP();
  };

  const handleClose = () => {
    setOtp('');
    setGeneratedOtp('');
    setTimer(OTP_EXPIRY_TIME);
    setCanResend(false);
    onClose();
  };

  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const maskPhone = (number) => {
    if (!number) return '';
    const last4 = number.slice(-4);
    return `+91 ******${last4}`;
  };

  return (
    <Modal
      visible={isVisible}
      transparent
      animationType="fade"
      onRequestClose={handleClose}
    >
      <View style={styles.overlay}>
        <View style={styles.container}>
          {/* Header */}
          <View style={styles.header}>
            <View style={styles.iconBadge}>
              <Icons.FontAwesome name="shield" size={20} color="#094485" />
            </View>
            <TouchableOpacity onPress={handleClose} style={styles.closeBtn}>
              <Icons.FontAwesome name="times" size={18} color="#999" />
            </TouchableOpacity>
          </View>

          {/* Content */}
          <Text style={styles.title}>Verify Mobile</Text>
          <Text style={styles.subtitle}>Code sent to {maskPhone(mobileNumber)}</Text>

          {/* OTP Input */}
          <View style={styles.inputSection}>
            <OtpTextInput callBack={handleOtpCallback} />
          </View>

          {/* Timer & Resend */}
          <View style={styles.footer}>
            <View style={styles.timerBox}>
              {timer > 0 ? (
                <Text style={styles.timerText}>{formatTime(timer)}</Text>
              ) : (
                <Text style={styles.expiredText}>Expired</Text>
              )}
            </View>

            <TouchableOpacity
              onPress={handleResendOTP}
              disabled={!canResend || isSendingOtp}
              style={styles.resendBtn}
            >
              {isSendingOtp ? (
                <ActivityIndicator size="small" color="#094485" />
              ) : (
                <Text style={[
                  styles.resendText,
                  (!canResend || isSendingOtp) && styles.resendDisabled
                ]}>
                  Resend Code
                </Text>
              )}
            </TouchableOpacity>
          </View>

          {/* Loading Overlay */}
          {isLoading && (
            <View style={styles.loadingOverlay}>
              <ActivityIndicator size="large" color="#094485" />
            </View>
          )}
        </View>
      </View>
    </Modal>
  );
};

const styles = StyleSheet.create({
  overlay: {
    flex: 1,
    backgroundColor: 'rgba(0, 0, 0, 0.5)',
    justifyContent: 'center',
    alignItems: 'center',
    padding: 20,
  },
  container: {
    backgroundColor: '#fff',
    borderRadius: 16,
    width: '100%',
    maxWidth: 340,
    padding: 24,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.25,
    shadowRadius: 8,
    elevation: 5,
  },
  header: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: 16,
  },
  iconBadge: {
    width: 40,
    height: 40,
    borderRadius: 20,
    backgroundColor: '#E8F4FF',
    justifyContent: 'center',
    alignItems: 'center',
  },
  closeBtn: {
    width: 32,
    height: 32,
    borderRadius: 16,
    backgroundColor: '#f5f5f5',
    justifyContent: 'center',
    alignItems: 'center',
  },
  title: {
    fontSize: 20,
    fontWeight: '700',
    color: '#1a1a1a',
    marginBottom: 4,
  },
  subtitle: {
    fontSize: 13,
    color: '#666',
    marginBottom: 20,
  },
  inputSection: {
    marginBottom: 20,
  },
  footer: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
  },
  timerBox: {
    paddingVertical: 8,
    paddingHorizontal: 12,
    backgroundColor: '#f8f9fa',
    borderRadius: 8,
  },
  timerText: {
    fontSize: 13,
    color: '#666',
    fontWeight: '600',
  },
  expiredText: {
    fontSize: 13,
    color: '#dc3545',
    fontWeight: '600',
  },
  resendBtn: {
    paddingVertical: 8,
    paddingHorizontal: 12,
  },
  resendText: {
    fontSize: 14,
    color: '#094485',
    fontWeight: '700',
  },
  resendDisabled: {
    color: '#ccc',
  },
  loadingOverlay: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    backgroundColor: 'rgba(255, 255, 255, 0.9)',
    borderRadius: 16,
    justifyContent: 'center',
    alignItems: 'center',
  },
});

export default OTPVerificationModal;