export function getResultViewObservedvalueTextvalidate(
  value,
  minvalue,
  maxvalue,
  datatype,
) {
  switch (datatype) {
    case 'integer':
    case 'numeric':
      if (minvalue != null && minvalue != undefined && value < minvalue) {
        return colors.color_resulttext_low;
      } else if (
        maxvalue != null &&
        maxvalue != undefined &&
        value > maxvalue
      ) {
        return colors.color_resulttext_high;
      } else {
        return colors.color_resulttext_normal;
      }
      break;
    default:
      return colors.color_resulttext_normal;
  }
}

