import React, { useMemo } from 'react';
import { View, Text, TouchableOpacity, StyleSheet, ScrollView } from 'react-native';
import FastImage from 'react-native-fast-image';
import { normalize } from '../CommonStyle/componentStyle';
import { APIURL } from '../Common/apiConstants';
import { CShadowDynamic } from '../CommonStyle/ComponentFunctions';
import HOCIcons from '../HOC/HOCIcons';
import moment from 'moment';

export default function CInfoCard({
  profile,
  displayData,
  apiData,
  onPress = null,
  showImage = true,
  cardStyle = {}
}) {
  // 1. Data Merging & Extraction
  // Priority: API Data > Display Data (passed from list) > Profile object
  const mergedData = useMemo(() => {
    const api = apiData?.data ?? apiData?.result ?? apiData ?? {};
    const display = displayData ?? {};
    const prof = profile ?? {};

    return {
      firstname: api.firstname ?? prof.firstname ?? '',
      lastname: api.lastName ?? prof.lastName ?? '',
      donationid: api.donationid ?? prof.donationid ?? '',
      patientName: (api.firstname || api.lastName)
        ? `${api.firstname} ${api.lastName}`
        : (prof.patientname ?? display.patientname ?? 'Unknown Name'),
      patientNo: api.donorid ?? api.code ?? prof.patientno ?? display.hopapatient ?? 'N/A',
      age: api.age ?? prof.age ?? 'N/A',
      gender: api.gender ?? prof.gender ?? 'N/A',
      mobile: api.mobile ?? prof.mobileno ?? 'N/A',
      place: api.houseName ?? api.address ?? prof.place ?? prof.subheading3 ?? 'N/A',
      image: api.imageurl ?? prof.patientimage ?? null,
      status: api.status ?? prof.logo1 ?? '',
      statusDisplay: api.statusDisplay ?? prof.logo1Display ?? (api.status ?? prof.logo1 ?? ''),
      bloodGroup: prof.bloodGroup ?? display.leftcontent?.[0]?.value ?? 'N/A',
      donationStart: prof.donationstart ?? null,
      vitals: prof.vitalsdetails ?? [],
      allergies: Array.isArray(api.allergies) ? api.allergies : (Array.isArray(prof.allergies) ? prof.allergies : [])
    };
  }, [apiData, displayData, profile]);

  const {
    patientName, patientNo, age, gender, mobile, place,
    image, status, statusDisplay, bloodGroup, donationStart, vitals, allergies, donationid
  } = mergedData;

  // Formatting Helpers
  const formatValue = (val) => (!val || val === 'null') ? 'N/A' : val;
  const getStatusColor = (s) => {
    const statusUpper = (s || "").toUpperCase();
    switch (statusUpper) {
      case "BLED": return "#9C27B0";
      case "DEFERRED": return "#D32F2F";
      case "ACCEPTED": return "#1976D2";
      case "READY": return "#388E3C";
      case "Fit": return "#388E3C";
      case "PENDING": return "#FBC02D";
      default: return "#757575";
    }
  };
  const statusColor = getStatusColor(status);

  const activeAllergies = allergies.filter(a => a.selected === 1);

  // Components
  const InfoRow = ({ icon, label, value, highlight = false, isLast = false }) => (
    <View style={[styles.infoRow, isLast && { borderBottomWidth: 0 }]}>
      <View style={styles.infoRowIcon}>
        <HOCIcons.MaterialCommunityIcons name={icon} size={normalize(16)} color="#90A4AE" />
      </View>
      <View style={styles.infoRowContent}>
        <Text style={styles.infoLabel}>{label}</Text>
        <Text style={[styles.infoValue, highlight && { color: '#094485', fontWeight: 'bold' }]}>
          {formatValue(value)}
        </Text>
      </View>
    </View>
  );

  const StatBox = ({ label, value, icon, color = '#555' }) => (
    <View style={styles.statBox}>
      <View style={[styles.statIconCircle, { backgroundColor: color + '20' }]}>
        <HOCIcons.MaterialCommunityIcons name={icon} size={normalize(18)} color={color} />
      </View>
      <Text style={styles.statValue} numberOfLines={1} adjustsFontSizeToFit>{value}</Text>
      <Text style={styles.statLabel}>{label}</Text>
    </View>
  );

  return (
    <View style={[styles.container, cardStyle]}>

      {/* --- Profile Header --- */}
      <ScrollView
        showsVerticalScrollIndicator={false}
        contentContainerStyle={{ paddingBottom: 20 }}
        style={{ flex: 1 }}
      >
        {/* --- Profile Header --- */}
        <View style={styles.header}>
          <View style={styles.profileRow}>
            <View style={styles.avatarContainer}>
              {image ? (
                <FastImage
                  source={{ uri: image.startsWith('http') ? image : `${APIURL}bldfile/filedownload/patientprofile/${image}` }}
                  style={styles.avatar}
                  resizeMode={FastImage.resizeMode.cover}
                />
              ) : (
                <View style={[styles.avatar, styles.placeholderAvatar]}>
                  <Text style={styles.placeholderText}>{patientName.charAt(0)}</Text>
                </View>
              )}
            </View>

            <View style={styles.profileInfo}>
              <Text style={styles.name}>{patientName}</Text>
              <View style={styles.idRow}>
                <Text style={styles.idLabel}>ID: </Text>
                <Text style={styles.idText}>{patientNo}</Text>
              </View>
              {statusDisplay ? (
                <Text style={[styles.statusTextPlain, { color: statusColor }]}>
                  {statusDisplay}
                </Text>
              ) : null}
            </View>
          </View>
        </View>

        {/* --- Key Info Row (Stats) --- */}
        <View style={styles.keyInfoContainer}>
          <View style={styles.keyInfoItem}>
            <Text style={styles.keyInfoLabel}>Gender</Text>
            <Text style={styles.keyInfoValue}>{gender}</Text>
          </View>
          <View style={styles.verticalDivider} />
          <View style={styles.keyInfoItem}>
            <Text style={styles.keyInfoLabel}>Age</Text>
            <Text style={styles.keyInfoValue}>{String(age).split(' ')[0]} Yrs</Text>
          </View>
          <View style={styles.verticalDivider} />
          <View style={styles.keyInfoItem}>
            <Text style={styles.keyInfoLabel}>Blood Group</Text>
            <Text style={[styles.keyInfoValue, { color: '#D32F2F' }]}>{bloodGroup}</Text>
          </View>
        </View>

        <View style={styles.divider} />

        {/* --- Contact & Personal --- */}
        <View style={styles.section}>
          <Text style={styles.sectionHeader}>DONOR DETAILS</Text>
          <View style={styles.infoList}>
            <InfoRow icon="cellphone" label="Donation ID" value={donationid} highlight />
            <InfoRow icon="cellphone" label="Mobile" value={mobile} highlight />
            <InfoRow icon="map-marker" label="Location" value={place} />
            {donationStart && (
              <InfoRow icon="clock-time-four-outline" label="Donation Start" value={moment(donationStart).format('DD MMM YYYY, hh:mm A')} isLast />
            )}
          </View>
        </View>

        {/* --- Vitals Section --- */}
        {vitals && vitals.length > 0 && (
          <View style={styles.section}>
            <Text style={styles.sectionHeader}>VITALS</Text>
            <View style={styles.vitalsGrid}>
              {vitals.map((v, i) => (
                <View key={i} style={styles.vitalItem}>
                  <Text style={styles.vitalLabel}>{v.vitalsname}</Text>
                  <Text style={styles.vitalValue}>{v.value} <Text style={styles.vitalUnit}>{v.unit}</Text></Text>
                </View>
              ))}
            </View>
          </View>
        )}

        {/* --- Allergies Section --- */}
        <View style={styles.section}>
          <Text style={styles.sectionHeader}>ALLERGIES</Text>
          <View style={styles.allergiesWrapper}>
            {activeAllergies.length > 0 ? (
              activeAllergies.map((item, index) => (
                <View key={index} style={styles.allergyTag}>
                  <Text style={styles.allergyText}>• {item.displayvalue}</Text>
                </View>
              ))
            ) : (
              <Text style={styles.noAllergyText}>No Known Allergies</Text>
            )}
          </View>
        </View>
      </ScrollView>

    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    backgroundColor: '#fff',
    flex: 1,
    width: '100%',
  },
  header: {
    padding: normalize(15),
    borderBottomWidth: 1,
    borderBottomColor: '#eee',
    backgroundColor: '#fff',
  },
  profileRow: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  avatarContainer: {
    marginRight: normalize(15),
  },
  avatar: {
    width: normalize(60),
    height: normalize(60),
    borderRadius: normalize(4),
    borderWidth: 1,
    borderColor: '#ddd',
  },
  placeholderAvatar: {
    backgroundColor: '#f0f0f0',
    justifyContent: 'center',
    alignItems: 'center',
  },
  placeholderText: {
    fontSize: normalize(24),
    fontWeight: 'bold',
    color: '#555',
  },
  profileInfo: {
    flex: 1,
    justifyContent: 'center',
  },
  name: {
    fontSize: normalize(16),
    fontWeight: 'bold',
    color: '#000',
    marginBottom: normalize(2),
  },
  idRow: {
    flexDirection: 'row',
    marginBottom: normalize(4),
  },
  idLabel: {
    fontSize: normalize(12),
    color: '#666',
  },
  idText: {
    fontSize: normalize(12),
    color: '#333',
    fontWeight: '500',
  },
  statusTextPlain: {
    fontSize: normalize(12),
    fontWeight: 'bold',
    textTransform: 'uppercase',
  },

  // Clean Key Info Row
  keyInfoContainer: {
    flexDirection: 'row',
    paddingVertical: normalize(15),
    paddingHorizontal: normalize(15),
    backgroundColor: '#fff',
    alignItems: 'center',
  },
  keyInfoItem: {
    flex: 1,
    alignItems: 'center',
  },
  verticalDivider: {
    width: 1,
    height: '70%',
    backgroundColor: '#e0e0e0',
  },
  keyInfoLabel: {
    fontSize: normalize(11),
    color: '#777',
    marginBottom: normalize(2),
    textTransform: 'uppercase',
  },
  keyInfoValue: {
    fontSize: normalize(14),
    fontWeight: '600',
    color: '#222',
  },

  divider: {
    height: 1,
    backgroundColor: '#eee',
    marginHorizontal: normalize(15),
    marginBottom: normalize(15),
  },

  // Sections
  section: {
    paddingHorizontal: normalize(15),
    marginBottom: normalize(20),
  },
  sectionHeader: {
    fontSize: normalize(12),
    fontWeight: 'bold',
    color: '#444',
    marginBottom: normalize(10),
    borderLeftWidth: 3,
    borderLeftColor: '#094485',
    paddingLeft: normalize(8),
  },
  infoList: {
    backgroundColor: '#fff',
  },
  infoRow: {
    flexDirection: 'row',
    paddingVertical: normalize(8),
    alignItems: 'center',
    borderBottomWidth: 1,
    borderBottomColor: '#f5f5f5',
  },
  infoRowIcon: {
    width: normalize(25),
    alignItems: 'flex-start',
  },
  infoRowContent: {
    flex: 1,
  },
  infoLabel: {
    fontSize: normalize(11),
    color: '#888',
    marginBottom: 1,
  },
  infoValue: {
    fontSize: normalize(13),
    color: '#333',
  },

  // Vitals Grid
  vitalsGrid: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    borderTopWidth: 1,
    borderLeftWidth: 1,
    borderColor: '#e0e0e0',
  },
  vitalItem: {
    width: '33.33%',
    padding: normalize(10),
    borderRightWidth: 1,
    borderBottomWidth: 1,
    borderColor: '#e0e0e0',
    alignItems: 'center',
  },
  vitalLabel: {
    fontSize: normalize(10),
    color: '#666',
    marginBottom: normalize(4),
  },
  vitalValue: {
    fontSize: normalize(13),
    fontWeight: 'bold',
    color: '#000',
  },
  vitalUnit: {
    fontSize: normalize(10),
    fontWeight: 'normal',
    color: '#666',
  },

  // Allergies
  allergiesWrapper: {
    flexDirection: 'row',
    flexWrap: 'wrap',
  },
  allergyTag: {
    marginRight: normalize(15),
    paddingVertical: normalize(2),
  },
  allergyText: {
    color: '#D32F2F',
    fontSize: normalize(13),
    fontWeight: '500',
  },
  noAllergyText: {
    color: '#4CAF50',
    fontSize: normalize(13),
    fontStyle: 'italic',
  },
});