// MediaRecorder.js
import React, { useState, useRef } from 'react';
import {
  View,
  TouchableOpacity,
  Modal,
  StyleSheet,
  Text,
  ActivityIndicator,
  Platform,
  PermissionsAndroid,
  Image,
  Linking,
  Alert,
} from 'react-native';
import FontAwesome5 from 'react-native-vector-icons/FontAwesome5';
import { Camera, useCameraDevice, useCameraPermission, useCameraFormat } from 'react-native-vision-camera';
import ImagePicker from 'react-native-image-crop-picker';
import { AudioRecorder, AudioUtils } from 'react-native-audio';
import Video from 'react-native-video';
import { APIURL } from '../../Common/apiConstants';
import NetworkServiceCall from '../../Common/NetworkServiceCall';
import { notifyMessage } from '../../CommonStyle/ComponentFunctions';

// Media Retrieval URLs
const VIDEO_RETRIEVAL_BASE_URL = APIURL + `ayushfile/getFile/video/`;
const IMAGE_RETRIEVAL_BASE_URL = APIURL + `ayushfile/getFile/image/`;
const AUDIO_RETRIEVAL_BASE_URL = APIURL + `ayushfile/getFile/audio/`;

const MediaRecorder = ({
  questionId,
  onVideoCapture,
  onImageCapture,
  onAudioCapture,
  onVideoDelete,
  onImageDelete,
  onAudioDelete,
  existingVideo,
  existingImage,
  existingAudio,
  allowMedia = true,
}) => {
  const [cameraModal, setCameraModal] = useState({
    visible: false,
    type: null, // 'video', 'image', or 'audio'
  });
  const [previewModal, setPreviewModal] = useState({
    visible: false,
    type: null,
    uri: null,
  });
  const [isRecording, setIsRecording] = useState(false);
  const [isAudioRecording, setIsAudioRecording] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const cameraRef = useRef(null);
  const videoRef = useRef(null);
  const device = useCameraDevice('back');
  const { hasPermission, requestPermission } = useCameraPermission();
  const format = useCameraFormat(device, [
    { videoResolution: { width: 854, height: 480 } }, // Standard 480p resolution
    { fps: 30 }
  ]);

  // =========================================================
  // PREVIEW & DELETE HANDLERS
  // =========================================================
  const handleMediaClick = (type, fileName) => {
    if (!fileName) return;

    let uri = '';
    if (type === 'video') {
      uri = `${VIDEO_RETRIEVAL_BASE_URL}${fileName}`;
    } else if (type === 'image') {
      uri = `${IMAGE_RETRIEVAL_BASE_URL}${fileName}`;
    } else if (type === 'audio') {
      uri = `${AUDIO_RETRIEVAL_BASE_URL}${fileName}`;
    }

    setPreviewModal({
      visible: true,
      type: type,
      uri: uri,
    });
  };

  const handleDeleteMedia = (type) => {
    Alert.alert(
      'Delete Media',
      `Are you sure you want to delete this ${type}?`,
      [
        {
          text: 'Cancel',
          style: 'cancel'
        },
        {
          text: 'Delete',
          style: 'destructive',
          onPress: () => {
            if (type === 'video' && onVideoDelete) {
              onVideoDelete(questionId);
            } else if (type === 'image' && onImageDelete) {
              onImageDelete(questionId);
            } else if (type === 'audio' && onAudioDelete) {
              onAudioDelete(questionId);
            }
            setPreviewModal({ visible: false, type: null, uri: null });
            notifyMessage(`${type} deleted successfully`, 1);
          }
        }
      ]
    );
  };

  const closePreviewModal = () => {
    setPreviewModal({ visible: false, type: null, uri: null });
  };

  // =========================================================
  // PERMISSION HANDLING
  // =========================================================
  const handleCameraPress = async (type = 'video') => {
    let cameraPermission = hasPermission;

    if (type !== 'audio' && !cameraPermission) {
      cameraPermission = await requestPermission();
      if (!cameraPermission) {
        notifyMessage("Camera permission is required to capture media.", 2);
        return;
      }
    }

    if (type === 'video' || type === 'audio') {
      if (Platform.OS === 'android') {
        try {
          const granted = await PermissionsAndroid.request(
            PermissionsAndroid.PERMISSIONS.RECORD_AUDIO,
            {
              title: "Microphone Permission",
              message: "This app needs access to your microphone to record audio.",
              buttonPositive: "OK",
              buttonNegative: "Cancel",
            }
          );
          if (granted !== PermissionsAndroid.RESULTS.GRANTED) {
            notifyMessage("Microphone permission is required.", 2);
            return;
          }
        } catch (err) {
          console.warn(err);
          return;
        }
      }

      if (type === 'audio') {
        if (isAudioRecording) {
          stopAudioRecording();
        } else {
          startAudioRecording();
        }
      } else {
        setCameraModal({ visible: true, type: type });
      }
    } else {
      setCameraModal({ visible: true, type: type });
    }
  };

  // =========================================================
  // IMAGE CAPTURE
  // =========================================================
  const takePicture = async () => {
    if (cameraRef.current) {
      try {
        const photo = await cameraRef.current.takePhoto({
          qualityPrioritization: 'speed',
          flash: 'off',
          enableShutterSound: false
        });

        const photoUri = Platform.OS === 'android' ? 'file://' + photo.path : photo.path;

        const compressedImage = await ImagePicker.openCropper({
          path: photoUri,
          width: 1024,
          height: 768,
          cropping: false,
          mediaType: 'photo',
          includeExif: false,
          compressImageQuality: 0.5,
          freeStyleCropEnabled: true,
        });

        const serverFileName = await uploadImageFile(compressedImage.path, compressedImage.mime);

        if (serverFileName && onImageCapture) {
          onImageCapture(questionId, serverFileName);
        }

        closeCameraModal();
      } catch (error) {
        if (error.code !== 'E_PICKER_CANCELLED') {
          notifyMessage("Failed to process or take picture.", 2);
        }
      }
    }
  };

  const uploadImageFile = async (imagePath, fileType = 'image/jpeg') => {
    if (!imagePath) return null;

    setIsSubmitting(true);
    notifyMessage("Uploading image...", 1);

    const formData = new FormData();
    const localFileName = imagePath.split('/').pop();
    let mimeType = fileType;

    if (mimeType === 'image/jpeg' && localFileName.endsWith('.png')) {
      mimeType = 'image/png';
    }

    formData.append('file', {
      uri: Platform.OS === 'android' ? 'file://' + imagePath : imagePath,
      type: mimeType,
      name: localFileName
    });

    try {
      const response = await NetworkServiceCall('multiform', `${APIURL}ayushfile/fileupload/emr/image`, formData, null);

      if (response.httpstatus === 200 && response.data?.fileuri) {
        const serverFileName = response.data.fileuri;
        notifyMessage("Image upload complete!", 1);
        return serverFileName;
      } else {
        notifyMessage("Upload failed, please try again.", 2);
        return null;
      }
    } catch (error) {
      console.error('Error uploading image:', error);
      notifyMessage('Image upload failed.', 2);
      return null;
    } finally {
      setIsSubmitting(false);
    }
  };

  // =========================================================
  // VIDEO RECORDING
  const startRecording = async () => {
    if (cameraRef.current) {
      try {
        setIsRecording(true);
        await cameraRef.current.startRecording({
          videoCodec: 'h264', // h264 is more compatible and faster than h265
          videoBitRate: 'low', // Options: 'low', 'normal', 'high'
          fileType: 'mp4',
          onRecordingFinished: async (video) => {
            const serverFileName = await uploadVideoFile(video.path);

            if (serverFileName && onVideoCapture) {
              onVideoCapture(questionId, serverFileName);
            }
          },
          onRecordingError: (error) => {
            notifyMessage("Recording failed: " + error.message, 2);
            setIsRecording(false);
          }
        });
      } catch (error) {
        notifyMessage("Failed to start recording.", 2);
        setIsRecording(false);
      }
    }
  };

  const stopRecording = async () => {
    if (cameraRef.current) {
      try {
        await cameraRef.current.stopRecording();
        setIsRecording(false);
        setCameraModal({ visible: false, type: null });
      } catch (error) {
        setIsRecording(false);
      }
    }
  };

  const uploadVideoFile = async (videoPath) => {
    if (!videoPath) return null;

    setIsSubmitting(true);
    notifyMessage("Uploading video...", 1);

    const formData = new FormData();
    const localFileName = videoPath.split('/').pop();
    let fileType = 'video/mp4';

    if (localFileName.endsWith('.mov')) {
      fileType = 'video/quicktime';
    }

    formData.append('file', {
      uri: Platform.OS === 'android' ? 'file://' + videoPath : videoPath,
      type: fileType,
      name: localFileName
    });

    try {
      const response = await NetworkServiceCall('multiform', `${APIURL}ayushfile/fileupload/emr/video`, formData, null);

      if (response.httpstatus === 200 && response.data?.fileuri) {
        const serverFileName = response.data.fileuri;
        notifyMessage("Video upload complete!", 1);
        return serverFileName;
      } else {
        notifyMessage("Upload failed, please try again.", 2);
        return null;
      }
    } catch (error) {
      console.error('Error uploading video:', error);
      notifyMessage('Video upload failed.', 2);
      return null;
    } finally {
      setIsSubmitting(false);
    }
  };

  // =========================================================
  // AUDIO RECORDING
  // =========================================================
  const startAudioRecording = async () => {
    try {
      const audioPath = AudioUtils.DocumentDirectoryPath + `/audio_${Date.now()}.aac`;

      AudioRecorder.prepareRecordingAtPath(audioPath, {
        SampleRate: 22050,
        Channels: 1,
        AudioQuality: "Low",
        AudioEncoding: "aac",
      });

      AudioRecorder.onFinished = async (data) => {
        if (data.status === "OK") {
          const path = Platform.OS === 'ios' ? data.audioFileURL : data.audioFileURL.replace('file://', '');
          const serverFileName = await uploadAudioFile(path);

          if (serverFileName && onAudioCapture) {
            onAudioCapture(questionId, serverFileName);
          }
        } else {
          notifyMessage("Audio recording failed.", 2);
        }

        setIsAudioRecording(false);
      };

      await AudioRecorder.startRecording();
      setIsAudioRecording(true);
      notifyMessage("Recording audio...", 1);
    } catch (error) {
      console.error('Start audio recording error:', error);
      notifyMessage("Failed to start audio recording.", 2);
      setIsAudioRecording(false);
    }
  };

  const stopAudioRecording = async () => {
    try {
      if (isAudioRecording) {
        await AudioRecorder.stopRecording();
        notifyMessage("Audio recording stopped, processing upload...", 1);
      }
    } catch (error) {
      console.error('Stop audio recording error:', error);
      setIsAudioRecording(false);
    }
  };

  const uploadAudioFile = async (audioPath) => {
    if (!audioPath) return null;

    setIsSubmitting(true);
    notifyMessage("Uploading audio...", 1);

    const formData = new FormData();
    const localFileName = audioPath.split('/').pop();
    const fileUri = Platform.OS === 'android' ? 'file://' + audioPath : audioPath;

    formData.append('file', {
      uri: fileUri,
      type: 'audio/aac',
      name: localFileName
    });

    try {
      const response = await NetworkServiceCall('multiform', `${APIURL}ayushfile/fileupload/emr/audio`, formData, null);

      if (response.httpstatus === 200 && response.data?.fileuri) {
        const serverFileName = response.data.fileuri;
        notifyMessage("Audio upload complete!", 1);
        return serverFileName;
      } else {
        notifyMessage("Upload failed, please try again.", 2);
        return null;
      }
    } catch (error) {
      console.error('Error uploading audio:', error);
      notifyMessage('Audio upload failed.', 2);
      return null;
    } finally {
      setIsSubmitting(false);
    }
  };

  const startAudioPlayback = (audioFileName) => {
    if (audioFileName) {
      const audioUrl = `${AUDIO_RETRIEVAL_BASE_URL}${audioFileName}`;
      Linking.openURL(audioUrl).catch(err => {
        console.error('Failed to open audio URL:', err);
        notifyMessage("Could not start audio playback.", 2);
      });
    } else {
      notifyMessage("No audio file recorded for this question.", 2);
    }
  };

  const closeCameraModal = () => {
    if (isRecording) {
      stopRecording();
    }
    setCameraModal({ visible: false, type: null });
  };

  if (!allowMedia) return null;

  return (
    <View style={styles.mediaControlsContainer}>
      {/* VIDEO BUTTON */}
      {existingVideo ? (
        <TouchableOpacity
          style={styles.mediaPreviewContainer}
          onPress={() => handleMediaClick('video', existingVideo)}
        >
          <Video
            source={{ uri: `${VIDEO_RETRIEVAL_BASE_URL}${existingVideo}` }}
            style={styles.compactVideoPlayer}
            resizeMode="cover"
            paused={true}
            onError={(e) => console.error('Video Error:', e)}
          />
          <View style={styles.mediaOverlay}>
            <FontAwesome5 name="play-circle" size={12} color="white" />
          </View>
        </TouchableOpacity>
      ) : (
        <TouchableOpacity
          style={styles.compactCameraButton}
          onPress={() => handleCameraPress('video')}
        >
          <FontAwesome5 name="video" size={10} color="white" />
        </TouchableOpacity>
      )}

      {/* IMAGE BUTTON */}
      {existingImage ? (
        <TouchableOpacity
          style={styles.mediaPreviewContainer}
          onPress={() => handleMediaClick('image', existingImage)}
        >
          <Image
            source={{ uri: `${IMAGE_RETRIEVAL_BASE_URL}${existingImage}` }}
            style={styles.compactImagePreview}
          />
          <View style={styles.mediaOverlay}>
            <FontAwesome5 name="eye" size={10} color="white" />
          </View>
        </TouchableOpacity>
      ) : (
        <TouchableOpacity
          style={[styles.compactCameraButton, styles.compactImageButton]}
          onPress={() => handleCameraPress('image')}
        >
          <FontAwesome5 name="camera" size={10} color="white" />
        </TouchableOpacity>
      )}

      {/* AUDIO BUTTON */}
      {isAudioRecording || existingAudio ? (
        <TouchableOpacity
          style={[
            styles.compactAudioButton,
            isAudioRecording ? styles.compactAudioRecordingButton : styles.compactAudioRecordedButton,
          ]}
          onPress={() => {
            if (isAudioRecording) {
              stopAudioRecording();
            } else if (existingAudio) {
              handleMediaClick('audio', existingAudio);
            }
          }}
        >
          <FontAwesome5
            name={isAudioRecording ? "stop" : (existingAudio ? "music" : "microphone")}
            size={8}
            color="white"
          />
          <Text style={styles.compactAudioText}>
            {isAudioRecording ? "STOP" : (existingAudio ? "PLAY" : "REC")}
          </Text>
        </TouchableOpacity>
      ) : (
        <TouchableOpacity
          style={styles.compactAudioButton}
          onPress={() => handleCameraPress('audio')}
        >
          <FontAwesome5 name="microphone" size={8} color="white" />
          <Text style={styles.compactAudioText}>REC</Text>
        </TouchableOpacity>
      )}

      {/* PREVIEW MODAL */}
      {previewModal.visible && (
        <Modal
          visible={true}
          animationType="fade"
          transparent={false}
          onRequestClose={closePreviewModal}
        >
          <View style={styles.previewModal}>
            <View style={styles.previewHeader}>
              <Text style={styles.previewTitle}>
                {previewModal.type === 'video' ? 'Video Preview' :
                  previewModal.type === 'image' ? 'Image Preview' : 'Audio Playback'}
              </Text>
              <View style={styles.previewHeaderButtons}>
                <TouchableOpacity
                  onPress={() => handleDeleteMedia(previewModal.type)}
                  style={styles.deleteButton}
                >
                  <FontAwesome5 name="trash" size={20} color="#ff4444" />
                </TouchableOpacity>
                <TouchableOpacity onPress={closePreviewModal} style={styles.closeButton}>
                  <FontAwesome5 name="times" size={24} color="white" />
                </TouchableOpacity>
              </View>
            </View>

            <View style={styles.previewContent}>
              {previewModal.type === 'video' && (
                <Video
                  ref={videoRef}
                  source={{ uri: previewModal.uri }}
                  style={styles.fullVideo}
                  resizeMode="contain"
                  controls={true}
                  paused={false}
                />
              )}

              {previewModal.type === 'image' && (
                <Image
                  source={{ uri: previewModal.uri }}
                  style={styles.fullImage}
                  resizeMode="contain"
                />
              )}

              {previewModal.type === 'audio' && (
                <View style={styles.audioPreviewContainer}>
                  <FontAwesome5 name="music" size={80} color="#17a2b8" />
                  <Text style={styles.audioPreviewText}>Audio File</Text>
                  <TouchableOpacity
                    style={styles.playAudioButton}
                    onPress={() => startAudioPlayback(existingAudio)}
                  >
                    <FontAwesome5 name="play" size={20} color="white" />
                    <Text style={styles.playAudioText}>Play Audio</Text>
                  </TouchableOpacity>
                </View>
              )}
            </View>
          </View>
        </Modal>
      )}

      {/* CAMERA MODAL */}
      {cameraModal.visible && hasPermission && (cameraModal.type === 'video' || cameraModal.type === 'image') && device && (
        <Modal
          visible={true}
          animationType="slide"
          onRequestClose={closeCameraModal}
        >
          <View style={styles.cameraModal}>
            <View style={styles.cameraHeader}>
              <Text style={styles.cameraTitle}>
                {cameraModal.type === 'video' ? 'Record Video' : 'Capture Image'}
              </Text>
              <TouchableOpacity onPress={closeCameraModal} style={styles.closeButton}>
                <FontAwesome5 name="times" size={24} color="white" />
              </TouchableOpacity>
            </View>

            <Camera
              ref={cameraRef}
              style={StyleSheet.absoluteFill}
              device={device}
              isActive={cameraModal.visible}
              video={cameraModal.type === 'video'}
              audio={cameraModal.type === 'video'}
              photo={cameraModal.type === 'image'}
              format={format}
            />

            <View style={styles.cameraControls}>
              {cameraModal.type === 'video' ? (
                <>
                  {isRecording && (
                    <View style={styles.recordingIndicator}>
                      <View style={styles.recordingDot} />
                      <Text style={styles.recordingText}>Recording...</Text>
                    </View>
                  )}
                  <TouchableOpacity
                    style={[styles.recordButton, isRecording && styles.recordingButton]}
                    onPress={isRecording ? stopRecording : startRecording}
                  >
                    <View style={[styles.recordButtonInner, isRecording && styles.recordingButtonInner]} />
                  </TouchableOpacity>
                </>
              ) : (
                <TouchableOpacity style={styles.shutterButton} onPress={takePicture} />
              )}
            </View>
          </View>
        </Modal>
      )}

      {/* UPLOAD OVERLAY */}
      {isSubmitting && (
        <View style={styles.uploadOverlay}>
          <ActivityIndicator size="large" color="white" />
          <Text style={styles.uploadText}>Uploading...</Text>
        </View>
      )}
    </View>
  );
};

const styles = StyleSheet.create({
  mediaControlsContainer: {
    flexDirection: 'row',
    alignItems: 'center',
    marginTop: 10,
  },
  mediaPreviewContainer: {
    position: 'relative',
  },
  mediaOverlay: {
    position: 'absolute',
    top: 0,
    left: 4,
    right: 0,
    bottom: 0,
    backgroundColor: 'rgba(0,0,0,0.3)',
    justifyContent: 'center',
    alignItems: 'center',
    borderRadius: 3,
  },
  compactCameraButton: {
    backgroundColor: '#094485',
    padding: 4,
    borderRadius: 3,
    alignItems: 'center',
    justifyContent: 'center',
    width: 24,
    height: 20,
  },
  compactImageButton: {
    backgroundColor: '#094485',
    marginLeft: 4,
    width: 24,
    height: 20,
  },
  compactImagePreview: {
    width: 40,
    height: 24,
    borderRadius: 3,
    marginLeft: 4,
    resizeMode: 'cover',
    borderWidth: 1,
    borderColor: '#ffc107',
  },
  compactVideoPlayer: {
    width: 40,
    height: 24,
    borderRadius: 3,
    marginLeft: 4,
  },
  compactAudioButton: {
    backgroundColor: '#17a2b8',
    marginLeft: 4,
    width: 37,
    height: 20,
    flexDirection: 'row',
    justifyContent: 'center',
    alignItems: 'center',
    borderRadius: 3,
    paddingHorizontal: 4,
  },
  compactAudioRecordedButton: {
    backgroundColor: '#28a745',
  },
  compactAudioRecordingButton: {
    backgroundColor: '#dc3545',
  },
  compactAudioText: {
    color: 'white',
    fontSize: 8,
    fontWeight: 'bold',
    marginLeft: 2,
  },
  // Preview Modal Styles
  previewModal: {
    flex: 1,
    backgroundColor: 'black',
  },
  previewHeader: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    padding: 20,
    paddingTop: 40,
    backgroundColor: 'rgba(0,0,0,0.8)',
  },
  previewTitle: {
    color: 'white',
    fontSize: 18,
    fontWeight: 'bold',
  },
  previewHeaderButtons: {
    flexDirection: 'row',
    gap: 15,
  },
  deleteButton: {
    padding: 10,
  },
  closeButton: {
    padding: 10,
  },
  previewContent: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
  },
  fullVideo: {
    width: '100%',
    height: '100%',
  },
  fullImage: {
    width: '100%',
    height: '100%',
  },
  audioPreviewContainer: {
    justifyContent: 'center',
    alignItems: 'center',
  },
  audioPreviewText: {
    color: 'white',
    fontSize: 20,
    marginTop: 20,
    marginBottom: 30,
  },
  playAudioButton: {
    flexDirection: 'row',
    alignItems: 'center',
    backgroundColor: '#17a2b8',
    paddingHorizontal: 30,
    paddingVertical: 15,
    borderRadius: 25,
    gap: 10,
  },
  playAudioText: {
    color: 'white',
    fontSize: 16,
    fontWeight: 'bold',
  },
  // Camera Modal Styles (keep existing)
  cameraModal: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    backgroundColor: 'black',
    zIndex: 1000,
  },
  cameraHeader: {
    position: 'absolute',
    top: 40,
    left: 0,
    right: 0,
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    paddingHorizontal: 20,
    zIndex: 1001,
  },
  cameraTitle: {
    color: 'white',
    fontSize: 18,
    fontWeight: 'bold',
  },
  cameraControls: {
    position: 'absolute',
    bottom: 50,
    left: 0,
    right: 0,
    alignItems: 'center',
    zIndex: 1001,
  },
  recordButton: {
    width: 70,
    height: 70,
    borderRadius: 35,
    backgroundColor: 'white',
    justifyContent: 'center',
    alignItems: 'center',
  },
  recordingButton: {
    backgroundColor: '#ff4444',
  },
  recordButtonInner: {
    width: 60,
    height: 60,
    borderRadius: 30,
    backgroundColor: '#ff4444',
  },
  recordingButtonInner: {
    width: 30,
    height: 30,
    borderRadius: 5,
    backgroundColor: 'white',
  },
  recordingIndicator: {
    flexDirection: 'row',
    alignItems: 'center',
    marginBottom: 20,
  },
  recordingDot: {
    width: 10,
    height: 10,
    borderRadius: 5,
    backgroundColor: '#ff4444',
    marginRight: 8,
  },
  recordingText: {
    color: 'white',
    fontSize: 16,
    fontWeight: 'bold',
  },
  shutterButton: {
    backgroundColor: 'white',
    width: 70,
    height: 70,
    borderRadius: 35,
  },
  uploadOverlay: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    backgroundColor: 'rgba(0,0,0,0.7)',
    justifyContent: 'center',
    alignItems: 'center',
    zIndex: 2000,
  },
  uploadText: {
    color: 'white',
    fontSize: 16,
    marginTop: 10,
  },
});

export default MediaRecorder;
