import React, { useState } from 'react'
import { Text, TouchableOpacity } from 'react-native'
import FontAwesome5 from 'react-native-vector-icons/FontAwesome5';
import Icons from '../Common/Icons';
import { notifyMessage } from '../CommonStyle/ComponentFunctions';
import { normalize } from '../CommonStyle/componentStyle';

export default function CVectorIcon(props) {
    const [data, setData] = useState(props.data)
    return (
        <TouchableOpacity
            disabled={data?.disabled ?? false}
  style={{ alignItems: 'center', width: data?.width ? normalize(70) : normalize(50) }}
  onPress={() => data?.functionid ? getCallBack(data) : notifyMessage("Incorporate soon",3)}>
  <Icons.FontAwesome5
      name={data?.iconname ?? "file"}
      color={data?.iconcolor ?? "white"}
      size={normalize(data?.iconsize ?? 20)}
 />

            <Text
                numberOfLines={1}
                style={{
                    // flex:1,
                    width:normalize(50),
                    color: data?.fontcolor ?? "#fff",
                     textAlign: data?.textAlign ?? 'center',
   fontSize: normalize(data?.size ?? 10),
  fontWeight: data?.fontWeight ?? 'normal'
                }}>+ {data?.displaytext ?? ''}</Text>
        </TouchableOpacity>
    )

    function getCallBack(item) {
        props.callBack(item)
    }
}